EPIC_SCENES.market.job.gambler.push(
    { title:'판을 쓸어 담는다 — 도박사',
      text:`판이 다시 벌어진다.<br><br>
        이번에는 판돈이 가운데 쌓여 있다. 높다.<br>
        여섯 손이 전부 이쪽을 향한다. 들어오라는 뜻이다.<br><br>
        한 판이다. 한 판에 전부다.<br>
        <span style="color:#888; font-size:11px;">전부 따면 하려던 일이 끝난다.</span>`,
      opts:[
        { l:'① 패를 보지 않고 전부 건다.', dc:15, kind:'luck', p:1200, goal:true,
          good:`밀어 넣었다. 패는 엎어 둔 채로.<br><br>여섯이 차례로 젖힌다. 전부 같은 패다.<br>같은 패가 여섯이면 규칙상 전부 무효다.<br><br>이쪽 패를 젖혔다. 다른 패였다.<br>다른 것 하나뿐이라 이겼다.<br><br>쓸어 담는 동안 아무도 항의하지 않았다.`, flag:'wonAll',
          bad:`밀어 넣었다.<br><br>여섯이 젖힌다. 전부 다른 패다.<br>이쪽 것만 겹쳤다. 누군가와.<br>누구인지 보려고 고개를 들었는데 자리가 비어 있었다.`, poll:12 },
        { l:'② 패를 보고 절반만 건다.', dc:12, kind:'luck', p:900, goal:true,
          good:`절반만 걸었다. 이겼다.<br><br>남긴 절반이 아까웠는데, 두 번째 판에서 그 절반이 살렸다.<br>전부 따내긴 했다. 두 번에 나눠서.`,
          bad:`절반을 걸고 이겼다. 다음 판에서 나머지를 잃었다.<br><br>본전이다. 도박사에게 본전은 진 것이다.`, poll:7 },
        { l:'③ 판을 뒤엎는다.', dc:13, kind:'break', p:700,
          good:`탁자를 걷어찼다.<br><br>패가 흩어진다. 전부 백지다. 앞뒤 다.<br>처음부터 이길 수 있는 판이 아니었다.<br><br>흩어진 판돈을 주워 담았다. 아무도 말리지 않았다.`, flag:'flipped',
          bad:`엎으려는데 탁자가 무겁다.<br><br>바닥에 박혀 있다. 아니면 바닥이 탁자거나.<br>여섯이 동시에 이쪽을 봤다.`, poll:9 }
      ] }
);

