// 실패해도 위치는 알게 된다
(function patchDeepFlag() {
    const _epicPick = epicPick;
    epicPick = function (i) {
        const sc = er && er._sc;
        const o = sc && sc.opts ? sc.opts[i] : null;
        const r = _epicPick.apply(this, arguments);
        if (o && o.flag2 && er && !er.flags.deepFound) epicOpenDeep();
        return r;
    };
})();

