// 🃏 광대
// ==========================================
EPIC_SCENES.castle.job.jester = (EPIC_SCENES.castle.job.jester || []).concat([

{ title:'성 — 웃음이 나던 방',
  text:`웃던 것들이 있던 방이다.<br><br>
    의자가 둥글게 놓여 있고 전부 비어 있다.<br>
    바닥에 방울이 흩어져 있다. 밟으면 소리가 난다.<br><br>
    한 발짝도 소리 없이 건널 수가 없다.`,
  opts:[
    { l:'① 박자에 맞춰 밟는다.', mini:'beat', miniOpt:{ p:700, total:8, gap:760 },
      good:`밟는 소리가 박자가 된다.<br><br>소리를 없애는 게 아니라 음악으로 만든 것이다.<br>광대가 하는 일이 원래 그렇다.<br><br>건너편에 닿자 방울들이 일제히 한 번 울렸다. 박수 같았다.`, flag:'bellFloor',
      bad:`엇나갔다.<br><br>방울이 제멋대로 울린다. 시끄럽다.<br>시끄러운 건 광대에게도 나쁘다. 웃기지 않은 소음은 그냥 소음이다.` },
    { l:'② 방울을 전부 줍는다.', dc:13, p:500,
      good:`하나씩 주워 주머니에 넣었다. 스물셋 개다.<br><br>주울 때마다 소리가 났는데, 다 줍고 나니 조용하다.<br>주머니를 흔들자 한 번만 울린다. 뭉쳐서 하나가 됐다.`, flag:'bellsAll',
      bad:`줍는데 하나가 계속 굴러 달아난다.<br><br>쫓아갔다. 방 구석까지.<br>구석에서 멈췄다. 손에 쥐니 따뜻했다.`, poll:5 }
  ] },

{ title:'성 — 웃지 않는 자',
  text:`복도에 사람이 하나 서 있다.<br><br>
    다른 것들과 달리 얼굴이 있다. 무표정하다.<br>
    지나가려면 비켜 줘야 하는데 안 비킨다.<br><br>
    광대는 이런 걸 푸는 사람이다.`,
  opts:[
    { l:'① 흉내를 낸다.', dc:12, p:550,
      good:`그 사람 자세를 그대로 따라 했다. 무표정까지.<br><br>보고 있다가 입꼬리가 움직인다.<br>비켜 줬다. 비키면서 한 번 더 웃었다.`, flag:'mimicked',
      bad:`흉내를 내자 저쪽도 흉내를 낸다.<br><br>이쪽 자세를 정확히 따라 한다.<br>먼저 그만둔 건 이쪽이었다.`, poll:6 },
    { l:'② 넘어지는 척한다.', dc:11, p:500,
      good:`요란하게 넘어졌다.<br><br>웃지는 않았는데 손을 내밀었다.<br>잡고 일어섰다. 손이 차가웠다.`, flag:'fellDown',
      bad:`넘어졌는데 안 본다.<br><br>일어나는 동안 계속 앞만 본다.<br>혼자 넘어진 광대만큼 초라한 것도 없다.`, poll:4 },
    { l:'③ 비켜 달라고 말한다.', dc:15, kind:'bond', p:600,
      doom:{ title:'말을 건 대가', what:'말을 걸었습니다', dc:14, sec:70,
        text:`말을 걸었다.<br><br>그 사람이 고개를 돌린다. 처음으로.<br><span style="color:#d4af37;">"광대는 말을 하면 안 되는데."</span><br><br>목이 조인다. 손이 닿지 않았는데 조인다.<br>여기 광대에게는 말이 금지되어 있었다.`,
        dieText:`말을 한 광대는 광대가 아니다.<br><br>자리가 사라지면 사람도 사라진다.<br>여기서는 그렇다.` },
      good:`말을 걸었다.<br><br>그 사람이 놀란다. 놀란 얼굴이 웃긴다.<br>이쪽이 먼저 웃었다. 그러자 저쪽도 웃었다.`, flag:'spokeOut' }
  ] },

{ title:'성 — 거울 복도',
  text:`복도 한쪽이 전부 거울이다.<br><br>
    비친 것이 이쪽을 따라 한다. 당연한 일이다.<br>
    다만 반 박자 늦다.<br><br>
    늦는 건 따라 하는 쪽이다. 어느 쪽이 늦는지 봐야 한다.`,
  opts:[
    { l:'① 재주를 넘어 본다.', dc:13, kind:'evade', p:600,
      good:`넘었다. 거울 속이 반 박자 늦게 넘는다.<br><br>이쪽이 원본이라는 뜻이다.<br>확인하고 나니 마음이 놓였다.`, flag:'原本',
      bad:`넘었는데 거울이 먼저 넘었다.<br><br>반 박자 빨랐다.<br>확인하지 않는 편이 나았을 것이다.`, poll:8 },
    { l:'② 거울을 깬다.', dc:14, kind:'break', p:650,
      doom:{ title:'깨진 거울', what:'거울 조각에 둘러싸였습니다', dc:13, sec:65,
        text:`깼다.<br><br>조각이 바닥에 흩어진다. 조각마다 이쪽이 비친다.<br>스물셋 조각에 스물셋 개의 얼굴.<br><br>전부 웃고 있다. 이쪽은 안 웃었다.<br>조각들이 모여든다. 발밑으로.`,
        dieText:`조각이 모여 하나가 된다.<br><br>거울이 다시 섰다.<br>거울 속에 하나 서 있고, 이쪽은 없다.` },
      good:`깼다.<br><br>조각 속 얼굴들이 전부 한 번 웃고 사라졌다.<br>복도가 그냥 복도가 됐다.`, flag:'brokeMirror' }
  ] },

{ title:'성 — 웃음을 나눈다',
  text:`혼자 웃는 건 웃는 게 아니다.<br><br>
    광대의 일은 누구를 웃기는 것이고, 누구가 필요하다.<br>
    성 안 어딘가에 동료가 있다.`,
  opts:[
    { l:'① 부른다.', co:'call',
      coOpt:{ ask:'웃겨 볼 상대가 필요합니다.', sec:60, p:850,
        text:`웃길 대상이 있어야 광대다.`,
        doneText:`누가 왔다. 무슨 일인지도 모르고 왔다.<br><br>재주를 하나 넘었다. 그 사람이 웃었다.<br>웃는 소리가 성 안에 울렸다. 오래 울렸다.<br><br>울리는 동안 다른 소리들이 전부 멎어 있었다.`,
        failText:`아무도 오지 않았다.<br><br>혼자 재주를 넘었다. 혼자 웃었다.<br>혼자 웃는 광대를 여기서는 뭐라고 부르는지 모르겠다.` },
      good:`웃겼다.`, bad:`혼자 웃었다.`, flag:'sharedLaugh' }
  ] }
]);

EPIC_SCENES.market.job.jester = [
{ title:'장터 — 구경꾼',
  text:`좌판 사이에 빈자리가 있다.<br><br>
    공연하던 자리다. 바닥이 둥글게 닳아 있다.<br>
    여기 서면 사람이 모인다고 한다.<br><br>
    모이는 게 좋은 일인지는 모르겠다.`,
  opts:[
    { l:'① 선다.', dc:12, p:550,
      doom:{ title:'모인 것들', what:'둘러싸였습니다', dc:13, sec:70,
        text:`섰다. 모인다.<br><br>사방에서 온다. 좌판 주인들, 지나가던 것들, 고개 숙이고 있던 것들.<br>전부 고개를 들었다.<br><br>둘러싼다. 원이 좁아진다.<br>공연을 기다리는 게 아니라 다음 차례를 기다리는 자세다.`,
        dieText:`원이 닫혔다.<br><br>바닥이 왜 둥글게 닳았는지 알겠다.<br>여기 서던 사람이 여럿이었다는 뜻이다.` },
      good:`섰다. 모인다.<br><br>재주를 넘었다. 웃지는 않는데 흩어지지도 않는다.<br>세 번째 재주에서 하나가 박수를 쳤다.<br><br>박수 소리가 나자 나머지가 물러났다.`, flag:'performed' },
    { l:'② 비켜 간다.', dc:9, p:250,
      good:`둥근 자리를 밟지 않고 돌아갔다.<br><br>밟지 않으면 아무 일도 안 일어난다.<br>광대에게는 그게 제일 어려운 일이다.`,
      bad:`돌아가려는데 자리가 따라온다.<br><br>밟은 적 없는데 발밑이 둥글다.`, poll:5 }
  ] }
];

EPIC_SCENES.village.job.jester = [
{ title:'빈 마을 — 아무도 없는 관객',
  text:`마을 한가운데다.<br><br>
    집이 둘러서 있고 문이 전부 열려 있다.<br>
    관객석 같다. 빈 관객석.<br><br>
    공연하면 누가 볼 것 같다. 보는 것이 있을 것 같다.`,
  opts:[
    { l:'① 공연한다.', dc:12, p:600,
      good:`재주를 넘고, 넘어지고, 다시 일어섰다.<br><br>웃음소리가 났다. 집 안쪽에서.<br>스물셋 개의 집에서 동시에.<br><br>끝나고 인사했다. 박수는 없었다. 그래도 인사했다.`, flag:'villageShow',
      bad:`재주를 넘는데 아무 소리도 안 난다.<br><br>빈 집은 빈 집이다.<br>혼자 넘고 혼자 일어섰다.`, poll:5 },
    { l:'② 아이 목소리를 찾는다.', dc:13, kind:'sense', p:650,
      doom:{ title:'따라간 목소리', what:'집 안에 들어갔습니다', dc:14, sec:70,
        text:`목소리가 나는 집으로 들어갔다.<br><br>안쪽에 아무도 없다. 다만 밥상이 차려져 있고 자리가 하나 비어 있다.<br>앉으라는 목소리가 난다. 아이 목소리다.<br><br>문이 닫혔다. 광대는 부르면 가는 사람이다.<br>그게 문제였다.`,
        dieText:`자리에 앉았다.<br><br>앉고 나니 편하다. 일어설 이유가 떠오르지 않는다.<br>밖에서 누가 문을 닫는 소리가 났다.` },
      good:`목소리를 따라갔다. 집 앞까지.<br><br>안 들어갔다. 문간에서 재주를 하나 넘었다.<br>웃음소리가 났다. 그걸로 됐다.<br><br>들어가지 않는 것도 광대의 기술이다.`, flag:'stayedOut' }
  ] }
];

