EPIC_SCENES.castle.job.spy = (EPIC_SCENES.castle.job.spy || []).concat([

{ title:'성 — 두 개의 이름',
  text:`옷장이 있다.<br><br>
    두 벌이 걸려 있다. 한쪽은 성의 것, 한쪽은 바깥 것.<br>
    밀정은 둘 다 입을 수 있어야 한다.<br><br>
    다만 지금 입은 것은 어느 쪽도 아니다.`,
  opts:[
    { l:'① 성의 옷을 입는다.', dc:11, kind:'hide', p:500,
      good:`갈아입었다. 맞는다.<br><br>복도를 지나는데 아무도 안 본다.<br>여기 사람처럼 보인다는 뜻이다.<br><br>여기 사람처럼 보이는 게 좋은 일인지는 모르겠다.`, flag:'insideCoat',
      bad:`입었는데 소매가 짧다.<br><br>입던 사람이 더 작았다.<br>작은 사람이 여기 있었다는 뜻이다.`, poll:5 },
    { l:'② 둘 다 챙긴다.', dc:13, p:600,
      good:`둘 다 말아서 품에 넣었다.<br><br>어느 쪽이든 필요할 때 꺼내면 된다.<br>밀정이 무거운 건 그래서다.`, flag:'bothCoats',
      bad:`챙기려는데 두 벌이 붙어 있다.<br><br>꿰매져 있다. 안쪽에서.<br>누가 두 벌을 하나로 만들어 두었다.`, poll:6 },
    { l:'③ 벗은 채로 간다.', dc:15, kind:'evade', p:700,
      doom:{ title:'이름 없이', what:'어느 쪽도 아닌 채로 들켰습니다', dc:14, sec:70,
        text:`아무것도 안 입고 지나갔다. 원래 입던 대로.<br><br>복도 중간에서 멈춰 섰다.<br>양쪽에서 사람이 온다. 성의 옷과 바깥 옷.<br><br>둘 다 이쪽을 본다. 둘 다 자기 쪽이 아니라는 눈빛이다.<br>밀정은 양쪽에 속하지만, 어느 쪽도 아니면 아무것도 아니다.`,
        dieText:`양쪽이 동시에 손을 뻗었다.<br><br>어느 쪽으로 끌려갔는지는 모르겠다.<br>둘 다였을 수도 있다.` },
      good:`그냥 지나갔다.<br><br>옷이 아니라 걸음이 사람을 정한다.<br>여기 사람처럼 걸으니 아무도 안 봤다.`, flag:'walkedPlain' }
  ] },

{ title:'성 — 엿듣는 자리',
  text:`벽이 얇은 자리가 있다.<br><br>
    반대쪽에서 말소리가 난다. 둘이다.<br>
    말이 안 들리는데 박자는 들린다.<br><br>
    박자만으로도 알아낼 수 있는 게 있다.`,
  opts:[
    { l:'① 박자를 센다.', mini:'beat', miniOpt:{ p:750, total:10, gap:700 },
      good:`박자를 따라갔다.<br><br>주고받는 간격이 일정하다. 대화가 아니라 암송이다.<br>같은 말을 반복하고 있었다.<br><br>스물셋 번 반복했다. 스물넷 번째에 멎었다.`, flag:'chantCount',
      bad:`박자를 놓쳤다.<br><br>박자가 끊기더니 이쪽 벽을 두드린다.<br>같은 박자로.` },
    { l:'② 구멍을 낸다.', dc:13, kind:'break', p:550,
      good:`벽이 무르다. 손가락으로 팠다.<br><br>반대쪽이 보인다. 방이 비어 있다.<br>말소리는 계속 난다. 아무도 없는 방에서.`, flag:'emptyTalk',
      bad:`파는 중에 반대쪽에서도 팠다.<br><br>손가락이 마주쳤다.<br>뺐다. 반대쪽 손은 안 뺐다.`, poll:8 }
  ] },

{ title:'성 — 전언을 맡는다',
  text:`지하에서 하나가 올라왔다.<br><br>
    얼굴을 가렸고 손만 내민다. 봉인된 것이 쥐여 있다.<br>
    받으면 전해야 한다. 안 받으면 여기까지다.<br><br>
    <span style="font-size:11px; color:#888;">밀정은 대개 받는다.</span>`,
  opts:[
    { l:'① 받는다.', dc:10, p:450,
      good:`받았다. 가볍다.<br><br>봉인에 도장이 찍혀 있다. 처음 보는 문양이다.<br>주머니 깊이 넣었다.`, flag:'gotMsg',
      bad:`받는 순간 손이 잡힌다.<br><br>놓아 주지 않는다. 전하고 오라는 뜻인지, 가지 말라는 뜻인지.<br>억지로 뺐다.`, poll:6 },
    { l:'② 내용을 확인하고 받는다.', dc:14, kind:'gaze', p:650,
      doom:{ title:'봉인', what:'봉인을 뜯었습니다', dc:14, sec:70,
        text:`봉인을 뜯었다.<br><br>안에 이름이 하나 적혀 있다. 이쪽 이름이다.<br>전언이 아니라 명부였다.<br><br>고개를 드니 내밀던 손이 사라졌다.<br>대신 복도 양쪽에서 발소리가 온다. 봉인을 뜯은 밀정은 밀정이 아니다.`,
        dieText:`밀정의 규칙은 하나다. 읽지 않는 것.<br><br>읽은 순간 전할 사람이 아니라 전해질 내용이 된다.` },
      good:`봉인 틈으로 비춰 봤다. 뜯지는 않고.<br><br>이름이 하나 적혀 있다. 모르는 이름이다.<br>다행이었다. 그대로 넣었다.`, flag:'peeked' },
    { l:'③ 받지 않는다.', dc:9, p:300,
      good:`고개를 저었다.<br><br>손이 거둬진다. 서운해하지 않는다.<br>다음 사람에게 내밀 것이다.`,
      bad:`거절했는데 품에 들어와 있다.<br><br>언제 넣었는지 모르겠다.<br>버릴 수도 없다. 버리면 그것도 전달이다.`, poll:5 }
  ] },

{ title:'성 — 양쪽에 알린다',
  text:`두 진영 다 이쪽을 자기 편으로 안다.<br><br>
    그게 밀정의 위치고, 그 위치는 오래 못 간다.<br>
    지금 한쪽을 고르면 나머지가 적이 된다.<br><br>
    고르지 않으면 양쪽이 적이 된다.`,
  opts:[
    { l:'① 동료를 증인으로 세운다.', co:'witness',
      coOpt:{ ask:'양쪽에 전한 것을 봐 줄 사람이 필요합니다.', sec:65, p:900,
        text:`혼자 전하면 어느 쪽에서도 안 믿는다.<br>본 사람이 있으면 다르다.`,
        doneText:`동료가 옆에 섰다.<br><br>양쪽에 같은 말을 했다. 둘 다 들었고, 증인이 있었다.<br>믿든 안 믿든 전한 것은 전한 것이 됐다.<br><br>밀정의 일은 거기까지다.`,
        failText:`혼자 전했다.<br><br>양쪽 다 고개를 끄덕였다. 끄덕이기만 했다.<br>믿은 것 같지는 않다.` },
      good:`전했다.`, bad:`혼자 전했다.`, goal:true },
    { l:'② 양쪽에 다른 말을 한다.', dc:16, kind:'evade', p:800,
      doom:{ title:'두 말', what:'양쪽에 다른 말을 했습니다', dc:15, sec:75,
        text:`한쪽에는 이렇게, 다른 쪽에는 저렇게.<br><br>오래 해 온 일이다. 능숙했다.<br>다만 이번에는 두 쪽이 만났다.<br><br>복도 한가운데서. 이쪽을 사이에 두고.<br>서로에게 물어본다. 대답이 다르다.`,
        dieText:`양쪽이 동시에 이쪽을 봤다.<br><br>밀정이 죽는 방식은 대개 이렇다.<br>적에게가 아니라 양쪽 모두에게.` },
      good:`두 말을 했고 둘 다 믿었다.<br><br>능숙했다. 능숙한 게 무서웠다.<br>언제부터 이렇게 잘하게 됐는지 모르겠다.`, flag:'twoTongues', goal:true }
  ] }
]);

EPIC_SCENES.market.job.spy = [
{ title:'장터 — 표식을 남긴다',
  text:`좌판 기둥에 분필 자국이 있다.<br><br>
    밀정이 쓰는 표식이다. 누가 먼저 왔다는 뜻.<br>
    옆에 새로 그을 자리가 있다.<br><br>
    남기면 다음 사람이 읽는다. 다음 사람이 누구일지는 모른다.`,
  opts:[
    { l:'① 본 것을 남긴다.', dc:11, kind:'bond', p:500,
      good:`그었다. 여기 본 것을 표식으로.<br><br>다음에 오는 사람이 덜 헤맬 것이다.<br>그게 밀정이 남기는 유일한 것이다.`, flag:'leftMark',
      bad:`긋는데 분필이 부서진다.<br><br>손가락으로 그었다. 손가락도 지워진다.<br>지워지는 자국이었다.`, poll:4 },
    { l:'② 앞 사람 표식을 읽는다.', dc:12, kind:'gaze', p:550,
      good:`읽었다. <span style="color:#d4af37;">"스물셋 확인. 하나 못 찾음."</span><br><br>번호가 붙어 있다. 스물셋.<br>이쪽이 스물넷째다.`, flag:'prevSpy',
      bad:`읽는데 자국이 바뀐다.<br><br>읽을 때마다 다른 내용이 된다.<br>세 번 읽고 그만뒀다.`, poll:5 },
    { l:'③ 지운다.', dc:13, p:450,
      doom:{ title:'지운 표식', what:'표식을 지웠습니다', dc:13, sec:65,
        text:`지웠다. 앞 사람이 남긴 것을.<br><br>지우자 기둥이 미지근해진다.<br>표식은 기둥에 그은 게 아니었다. 기둥이 그은 것이었다.<br><br>사방의 기둥에 같은 표식이 떠오른다.<br>전부 이쪽을 향해 있다.`,
        dieText:`표식이 이쪽으로 옮겨 온다.<br><br>팔에, 목에, 얼굴에.<br>다음 사람이 읽을 것이다.` },
      good:`지웠다.<br><br>뒤쫓는 쪽이 못 읽게 하려는 것이다.<br>앞 사람에게는 미안하지만 그게 규칙이다.`, flag:'erasedMark' }
  ] }
];

EPIC_SCENES.tower.job.spy = [
{ title:'탑 — 내려다보기',
  text:`탑에서는 전부 보인다.<br><br>
    누가 어디 있는지, 어디로 가는지.<br>
    밀정에게 이만한 자리가 없다.<br><br>
    다만 보이는 만큼 보인다.`,
  opts:[
    { l:'① 동료들 위치를 외운다.', dc:12, kind:'sense', p:600,
      good:`전부 외웠다. 누가 어디 있는지.<br><br>내려가서도 알 것이다. 부르면 닿을 거리인지 아닌지도.<br>밀정이 하는 일 중에 제일 쓸모 있는 일이다.`, flag:'mappedAll',
      bad:`외우는데 위치가 바뀐다.<br><br>움직여서가 아니라 자리가 바뀐다.<br>세 번 다시 봤다.`, poll:6 },
    { l:'② 동료에게 알려 준다.', co:'handoff',
      coOpt:{ ask:'위에서 본 것을 전하려 합니다.', sec:55, p:750,
        text:`여기서 보이는 것을 아래 사람은 못 본다.`,
        doneText:`올라온 사람에게 보여 줬다.<br><br>손가락으로 짚어 가며. 저기가 어디고 저건 뭐고.<br>같이 보고 나니 확실히 보였다.<br><br>혼자 본 것은 봤다고 하기 어렵다.`,
        failText:`아무도 안 올라왔다.<br><br>혼자 보고 혼자 내려갔다.<br>내려가니 잊었다.` },
      good:`전했다.`, bad:`혼자 봤다.` }
  ] }
];
;

