EPIC_SCENES.ruin.job.swordsman = (EPIC_SCENES.ruin.job.swordsman || []).concat([

{ title:'폐허 — 연습하던 자리',
  text:`기둥 사이 바닥이 닳아 있다.<br><br>
    발을 놓던 자리다. 왼발 자리가 더 깊다.<br>
    같은 자세로 오래 섰다는 뜻이다.<br><br>
    그 자리에 서 보면 몸이 어디로 움직여야 하는지 안다.`,
  opts:[
    { l:'① 그 자세로 서서 휘둘러 본다.', mini:'beat', miniOpt:{ p:700, total:9, gap:730 },
      good:`박자가 잡힌다. 하나, 둘, 셋에 베고 넷에 거둔다.<br><br>기둥의 칼자국이 그 박자에 맞춰 나 있었다.<br>같은 사람이 같은 박자로 수천 번 벴다는 뜻이다.<br><br>마지막 한 번에 팔이 저절로 멎었다. 배운 적 없는 마무리였다.`, flag:'oldForm',
      bad:`박자가 어긋난다.<br><br>손목이 꺾인다. 제 힘에 제가 다쳤다.<br>누가 만들어 둔 박자에 억지로 맞출 일이 아니었다.` },
    { l:'② 발자국의 주인을 짐작해 본다.', dc:12, kind:'sense', p:450,
      good:`보폭이 좁다. 키가 크지 않았다.<br><br>왼발이 깊은 건 오른손잡이라서다. 이쪽과 같다.<br>같은 체격, 같은 손. 그게 위로가 되지는 않았다.`, flag:'sameBuild',
      bad:`재어 보는데 자국이 바뀐다.<br><br>재는 동안 넓어졌다 좁아진다.<br>여럿이 같은 자리에 섰던 것이다.`, poll:5 }
  ] },

{ title:'폐허 — 무너지는 천장 무늬',
  text:`지붕은 없는데 천장 무늬가 떠 있다.<br><br>
    그 무늬가 내려온다. 아주 천천히.<br>
    닿으면 뭉개질 것이다. 뭉개진 것이 여럿 있었던 자국이 바닥에 있다.`,
  opts:[
    { l:'① 무늬를 벤다.', dc:14, p:650,
      doom:{ title:'천장', what:'천장 무늬에 눌리고 있습니다', dc:14, sec:70,
        text:`벴다. 칼이 지나간다. 아무것도 안 베인다.<br><br>무늬는 계속 내려온다. 이제 머리에 닿았다.<br>무겁다. 무게가 있는 그림이다.<br><br>무릎이 꺾인다. 칼을 세워 버텨 봤지만 칼이 휘었다.`,
        dieText:`바닥에 무늬가 하나 늘었다.<br><br>스물넷 줄 중 비어 있던 맨 윗줄이 채워졌다.` },
      good:`벴다. 무늬가 갈라진다.<br><br>갈라진 틈으로 하늘이 보인다. 진짜 하늘이다.<br>내려오던 것이 멎었다.<br><br>천장은 없었다. 있다고 적혀 있었을 뿐이다.`, flag:'cutCeiling' },
    { l:'② 피해서 지나간다.', dc:11, kind:'evade', p:400,
      good:`달려 지났다. 등 뒤에서 내려앉는 소리가 났다.<br><br>돌아보니 바닥에 무늬가 찍혀 있다.<br>사람 모양으로 비어 있는 자리가 하나 있다.`, flag:'dodgedCeil',
      bad:`피하다 발이 걸렸다.<br><br>어깨에 스쳤다. 스친 자리가 납작하다.<br>옷이 아니라 어깨가.`, poll:9 }
  ] },

{ title:'폐허 — 날이 무뎌진다',
  text:`칼을 본다.<br><br>
    날이 뿌옇다. 녹이 아니라 안개가 앉은 것 같다.<br>
    닦아도 안 지워진다. 안쪽에서 올라온 것이다.<br><br>
    여기서는 쇠도 무뎌진다.`,
  opts:[
    { l:'① 돌에 갈아 본다.', dc:12, p:500,
      good:`기둥 모서리에 갈았다. 불꽃이 안 튄다.<br><br>그래도 갈리긴 한다. 뿌연 것이 벗겨진다.<br>벗겨진 자리가 검다. 원래 검은 칼이었던 것 같다.`, flag:'blackBlade',
      bad:`갈수록 더 뿌예진다.<br><br>가는 쪽이 벗겨지는 게 아니라 옮겨 붙는다.<br>손바닥까지 뿌예졌다.`, poll:7 },
    { l:'② 대장장이를 부른다.', co:'call',
      coOpt:{ ask:'날이 무뎌졌습니다. 봐 줄 손이 필요합니다.', sec:60, p:800,
        text:`쇠를 아는 사람이면 알 것이다.`,
        doneText:`누가 왔다. 칼을 받아 들고 한참 보더니 되돌려 줬다.<br><br>말은 안 했다. 다만 손등으로 날을 한 번 훑었다.<br>그러자 뿌연 것이 가셨다.<br><br>어떻게 한 건지는 안 물었다. 물어도 대답 안 했을 것이다.`,
        failText:`아무도 오지 않았다.<br><br>무딘 채로 간다. 무딘 칼로도 벨 수는 있다.<br>다만 힘이 더 든다.` },
      good:`날이 섰다.`, bad:`무딘 채로 간다.`, flag:'sharpened' }
  ] },

{ title:'폐허 — 겨루는 것',
  text:`기둥 사이에서 뭔가 나온다.<br><br>
    사람 모양이고 칼을 들었다. 자세가 반듯하다.<br>
    배운 자세다. 이쪽과 같은 유파다.<br><br>
    먼저 치지 않는다. 기다린다.`,
  opts:[
    { l:'① 먼저 친다.', dc:14, p:700,
      doom:{ title:'먼저 친 쪽', what:'겨룸에서 밀리고 있습니다', dc:14, sec:75,
        text:`쳤다. 막힌다.<br><br>막는 자세까지 같다. 이쪽이 어디를 칠지 알고 있는 것이다.<br>당연하다. 같은 것을 배웠으니까.<br><br>받아치기가 온다. 피할 자리를 아는 것도 저쪽이다.<br>밀린다. 벽까지.`,
        dieText:`벽에 등이 닿았다.<br><br>같은 것을 배운 둘이 겨루면 먼저 친 쪽이 진다.<br>그 말을 스승에게 들었었다.` },
      good:`쳤다. 막혔다. 막힐 줄 알았다.<br><br>막히는 순간 손목을 틀었다. 배운 적 없는 움직임으로.<br>저쪽이 처음으로 물러섰다.<br><br>배운 것만으로는 안 된다는 걸 여기서 배웠다.`, flag:'struckFirst' },
    { l:'② 기다린다.', dc:13, kind:'sense', p:650,
      good:`기다렸다. 저쪽도 기다린다.<br><br>오래 서 있었다. 팔이 저릴 때쯤 저쪽이 칼을 내렸다.<br>내리고 물러났다.<br><br>겨루지 않고 이기는 법도 있다.`, flag:'waited',
      bad:`기다리는데 팔이 먼저 떨어졌다.<br><br>그 틈에 왔다. 어깨를 베였다.<br>깊지는 않다. 정확히 얕게 벴다. 봐준 것이다.`, poll:9 },
    { l:'③ 칼을 버린다.', dc:15, kind:'bond', p:800,
      good:`칼을 바닥에 놓았다.<br><br>저쪽이 멈춘다. 오래 본다.<br>그리고 자기 칼도 놓았다.<br><br>둘 다 맨손으로 마주 섰다. 아무 일도 안 일어났다.<br>일어나지 않은 것이 결말이었다.`, flag:'droppedBlade',
      bad:`버렸는데 저쪽이 안 멈춘다.<br><br>주우려는데 칼이 없다.<br>버린 자리에 없다.`, poll:11 }
  ] }
]);

EPIC_SCENES.gate.job.swordsman = [
{ title:'성문 — 베어 열던 자리',
  text:`아치 기둥에 깊은 자국이 하나 있다.<br><br>
    칼자국인데 너무 깊다. 돌을 이렇게 벨 수는 없다.<br>
    벤 게 아니라 돌이 갈라진 것을 칼 탓으로 돌린 것 같다.<br><br>
    자국에 손을 대면 미지근하다.`,
  opts:[
    { l:'① 같은 자리를 벤다.', dc:13, p:600,
      good:`벴다. 자국이 한 뼘 깊어진다.<br><br>안쪽에서 바람이 샌다. 이 돌 뒤에 공간이 있다.<br>몇 번 더 베면 뚫릴 것이다. 지금은 안 뚫었다.`, flag:'gateCrack',
      bad:`벴는데 칼이 튕긴다.<br><br>팔이 저리다. 자국은 그대로다.<br>낸 사람은 이쪽보다 세거나, 칼이 달랐다.`, poll:7 },
    { l:'② 파수꾼을 부른다.', co:'sync',
      coOpt:{ ask:'같이 밀어야 열립니다.', sec:60, p:850,
        text:`혼자 베어서 될 일이 아니다. 미는 손이 하나 더 필요하다.`,
        doneText:`둘이 동시에. 이쪽이 베고 저쪽이 밀었다.<br><br>돌이 통째로 밀려난다. 안쪽에 통로가 있다.<br>먼지가 가라앉을 때까지 둘 다 말이 없었다.`,
        failText:`혼자 베고 혼자 밀었다.<br><br>안 밀린다. 될 일이 아니었다.` },
      good:`열었다.`, bad:`안 열렸다.`, flag:'gateOpened' }
  ] }
];

EPIC_SCENES.forest.job.swordsman = [
{ title:'검은 숲 — 벨 수 없는 것',
  text:`나무가 길을 막는다.<br><br>
    베면 된다. 검사가 할 수 있는 일이다.<br>
    다만 이 숲의 나무는 미지근하고, 안쪽에서 소리가 난다.<br><br>
    벤다는 건 그 소리를 멈추는 일이다.`,
  opts:[
    { l:'① 벤다.', dc:12, p:550,
      doom:{ title:'벤 나무', what:'나무가 쓰러지고 있습니다', dc:13, sec:65,
        text:`벴다. 단번에 갈라진다. 너무 쉽게.<br><br>안에서 나던 소리가 멎는다.<br>그러자 주변 나무가 전부 이쪽으로 기운다.<br><br>기울던 게 아니라 향하던 것이었다.<br>한 그루가 넘어온다. 피할 자리가 없다.`,
        dieText:`나무가 덮쳤다.<br><br>안에서 나던 소리가 다시 들린다.<br>이번엔 이쪽 안쪽에서.` },
      good:`벴다. 갈라진 자리에서 수액이 아니라 물이 나온다.<br><br>맑다. 마실 수 있을 만큼.<br>주변 나무가 조금씩 바로 선다. 막고 있던 게 이 한 그루였다.`, flag:'felled' },
    { l:'② 돌아간다.', dc:10, p:300,
      good:`돌아갔다. 시간이 더 걸렸다.<br><br>검사가 베지 않고 가는 건 쉬운 일이 아니다.<br>그래도 갔다.`, flag:'wentAround',
      bad:`돌아가는데 길이 없다.<br><br>나무가 자리를 옮긴다. 막아서는 쪽으로.<br>결국 벨 수밖에 없었다.`, poll:6 }
  ] }
];

EPIC_SCENES.castle.job.swordsman = [
{ title:'성 — 벽에 걸린 칼들',
  text:`복도 벽에 칼이 걸려 있다.<br><br>
    스물셋 자루다. 전부 날이 아래를 향해 걸렸다.<br>
    쓰지 않겠다는 뜻으로 그렇게 건다.<br><br>
    걸이 하나가 비어 있다.`,
  opts:[
    { l:'① 이쪽 칼을 건다.', dc:13, kind:'bond', p:700,
      doom:{ title:'걸린 칼', what:'칼을 걸었습니다', dc:15, sec:70,
        text:`걸었다. 스물넷이 됐다.<br><br>걸자마자 손이 가벼워진다. 너무 가볍다.<br>다시 내리려는데 안 빠진다.<br><br>벽이 쥐고 있다. 칼만 쥔 게 아니다.<br>손도 같이 굳어 간다.`,
        dieText:`칼이 스물넷이 되고 사람이 하나 줄었다.<br><br>쓰지 않겠다는 뜻으로 거는 자리다.<br>다시 쓸 일은 없다.` },
      good:`걸었다. 스물넷이 됐다.<br><br>맞는 소리가 났다. 아귀가 맞는 소리.<br>잠시 뒤 도로 내렸다. 벽이 순순히 놓아줬다.<br><br>걸어 봤다는 것만으로 충분했다.`, flag:'hungBlade' },
    { l:'② 한 자루 꺼내 본다.', dc:12, p:550,
      good:`한 자루 빼 들었다. 가볍다.<br><br>날이 없다. 자루만 있고 날이 없는 칼이다.<br>스물셋 전부 그렇다. 확인하고 도로 걸었다.`, flag:'hollowBlades',
      bad:`빼려는데 안 빠진다.<br><br>걸린 게 아니라 벽에서 자란 것이다.<br>칼 모양의 벽이었다.`, poll:6 }
  ] }
];

