// 🔨 대장장이
// ==========================================
EPIC_SCENES.market.job.smith = (EPIC_SCENES.market.job.smith || []).concat([

{ title:'장터 — 대장간 자리',
  text:`좌판 끝에 화덕이 있다.<br><br>
    불이 꺼져 있다. 재가 식어 있고, 모루에 먼지가 앉았다.<br>
    망치는 자루만 남았다. 머리는 없다.<br><br>
    쓰던 사람이 급히 떠난 자리다.`,
  opts:[
    { l:'① 불을 지핀다.', dc:12, p:550,
      good:`재를 걷어 내고 숯을 넣었다. 붙는다.<br><br>불빛이 좌판 쪽을 비춘다. 고개 숙이고 있던 것들이 전부 물러난다.<br>불을 싫어하는 것들이었다.`, flag:'litForge',
      bad:`숯이 안 붙는다.<br><br>불씨를 넣으면 꺼진다. 바람도 없는데 꺼진다.<br>여기 불은 꺼져 있으라고 꺼 둔 것이었다.`, poll:5 },
    { l:'② 망치 머리를 찾는다.', dc:13, kind:'sense', p:600,
      good:`화덕 안쪽에 박혀 있다. 재 속에.<br><br>꺼내니 뜨겁다. 식은 화덕인데 뜨겁다.<br>자루에 끼우니 딱 맞는다.`, flag:'hammer',
      bad:`재를 헤집다 손을 데었다.<br><br>재가 식지 않았다.<br>밑에서 아직 타고 있었다는 뜻이다.`, poll:7 }
  ] },

{ title:'장터 — 배합',
  text:`화덕 옆에 쇳조각이 종류별로 놓여 있다.<br><br>
    섞는 비율이 정해져 있다. 벽에 적혀 있었을 텐데 지워졌다.<br>
    무게로 맞춰야 한다.<br><br>
    틀리면 부스러지는 쇠가 나온다.`,
  opts:[
    { l:'① 무게를 맞춰 넣는다.', mini:'scale', miniOpt:{ p:800, target:26, pool:[4,5,7,9,10,13] },
      good:`수평이 잡힌다.<br><br>녹여서 부으니 색이 곱다. 식히는 동안 소리가 났다.<br>쇠가 식을 때 나는 소리가 아니라, 숨 돌리는 소리에 가까웠다.`, flag:'alloy',
      bad:`기울었다.<br><br>부어 보니 색이 탁하다. 식자마자 금이 갔다.<br>다시 녹이려는데 안 녹는다. 한 번 실패한 쇠는 안 돌아온다.` },
    { l:'② 감으로 넣는다.', dc:14, p:600,
      good:`손이 안다. 눈금 없이 넣었다.<br><br>나온 쇠가 좋다. 배운 대로 한 것보다 낫다.<br>오래 한 손은 저울보다 정확하다.`, flag:'byHand',
      bad:`감이 어긋났다.<br><br>여기 쇠는 이쪽이 아는 쇠가 아니었다.<br>나온 것이 물러서 손으로 휘어진다.`, poll:6 }
  ] },

{ title:'장터 — 망치질',
  text:`벼릴 것이 있다.<br><br>
    쇠는 식기 전에 쳐야 하고, 박자가 어긋나면 결이 망가진다.<br>
    혼자 치면 박자는 지킬 수 있는데 잡아 줄 손이 없다.`,
  opts:[
    { l:'① 박자를 지켜 친다.', mini:'beat', miniOpt:{ p:750, total:10, gap:680 },
      good:`쳤다. 열 번.<br><br>결이 곧게 섰다. 두드릴 때마다 쇠가 대답하듯 울렸다.<br>마지막 한 번에 울림이 길게 남았다. 잘 됐다는 뜻이다.`, flag:'forged',
      bad:`박자가 어긋났다.<br><br>결이 엇갈린다. 엇갈린 쇠는 겉으론 멀쩡하고 쓰다가 부러진다.<br>알면서 그대로 뒀다. 다시 할 시간이 없었다.` },
    { l:'② 잡아 줄 사람을 부른다.', co:'sync',
      coOpt:{ ask:'집게를 잡아 줄 손이 필요합니다.', sec:60, p:900,
        text:`둘이 하면 결이 다르다.`,
        doneText:`누가 와서 집게를 잡았다.<br><br>말없이 잡고 있었다. 이쪽이 치는 동안 한 번도 안 흔들렸다.<br>다 치고 나서 둘 다 손을 털었다.<br><br>둘이 만든 것은 혼자 만든 것보다 오래 간다. 이유는 모르겠다.`,
        failText:`아무도 오지 않았다.<br><br>무릎으로 집게를 누르고 쳤다.<br>되긴 됐다. 무릎이 데었다.` },
      good:`벼렸다.`, bad:`혼자 벼렸다.` }
  ] },

{ title:'장터 — 불이 옮겨붙는다',
  text:`화덕 불이 커진다.<br><br>
    숯을 더 넣지 않았는데 커진다.<br>
    좌판 천에 옮겨붙었다. 천이 마른 소리를 내며 탄다.<br><br>
    끄지 않으면 장터가 탄다.`,
  opts:[
    { l:'① 화덕을 통째로 엎는다.', dc:14, kind:'break', p:700,
      doom:{ title:'번지는 불', what:'불에 둘러싸였습니다', dc:14, sec:65,
        text:`엎었다. 불이 바닥으로 쏟아진다.<br><br>사방으로 번진다. 좌판, 천막, 쌓인 물건.<br>여기 것들은 불을 무서워하는데, 무서워하면서도 안 도망간다.<br><br>둘러싼다. 불을 등지고 이쪽으로 온다.<br>불보다 이쪽이 가까워서다.`,
        dieText:`불이 좌판을 다 먹었다.<br><br>대장장이는 불을 다루는 사람이다.<br>다루는 것과 이기는 것은 다르다.` },
      good:`엎었다. 불이 흩어지며 약해진다.<br><br>재를 덮어 마저 껐다. 손이 데었다.<br>불이 꺼지자 좌판 주인들이 전부 고개를 숙였다.<br>인사였다.`, flag:'doused' },
    { l:'② 천을 걷어 낸다.', dc:12, p:550,
      good:`타는 천을 걷어 바닥에 던지고 밟았다.<br><br>불이 번지기 전에 잡았다.<br>발바닥이 뜨겁다. 신발이 얇았다.`, flag:'stomped',
      bad:`걷다가 손에 불이 옮겨붙었다.<br><br>털어 껐다. 소매가 탔다.<br>불은 잡았는데 천이 반쯤 탔다.`, poll:8 }
  ] },

{ title:'장터 — 남이 쓰던 연장',
  text:`연장통이 있다.<br><br>
    집게, 정, 줄. 손때가 묻어 있다.<br>
    손잡이 자국이 이쪽 손과 안 맞는다. 더 큰 손이었다.<br><br>
    남의 연장을 쓰는 건 대장장이에게 꺼림칙한 일이다.`,
  opts:[
    { l:'① 그대로 쓴다.', dc:11, p:450,
      good:`맞지 않는 대로 썼다.<br><br>손에 물집이 잡혔다. 그래도 일은 됐다.<br>일이 되는 게 먼저다.`, flag:'usedTools',
      bad:`쓰다가 손에서 미끄러졌다.<br><br>정이 튕겨 나가 어딘가에 박혔다.<br>소리가 오래 울렸다.`, poll:6 },
    { l:'② 손잡이를 고쳐 잡게 깎는다.', dc:13, p:600,
      good:`칼로 손잡이를 깎았다. 이쪽 손에 맞게.<br><br>깎아 낸 부스러기에 옛 손자국이 섞여 있다.<br>주머니에 넣었다. 왜 그랬는지는 모르겠다.`, flag:'reshaped',
      bad:`깎다가 손잡이가 갈라졌다.<br><br>안쪽이 비어 있다. 나무가 아니었다.<br>뼈였다.`, poll:9 }
  ] }
]);

EPIC_SCENES.ruin.job.smith = (EPIC_SCENES.ruin.job.smith || []).concat([
{ title:'폐허 — 박힌 쇠들',
  text:`기둥마다 쇠가 박혀 있다.<br><br>
    칼, 창, 못. 종류가 제각각이다.<br>
    전부 같은 높이에 박혀 있다. 어깨높이.<br><br>
    던져 박힌 게 아니라 눌러 박은 것이다.`,
  opts:[
    { l:'① 하나씩 뽑아 모은다.', dc:13, p:650,
      doom:{ title:'뽑은 자리', what:'기둥이 무너지고 있습니다', dc:13, sec:65,
        text:`뽑았다. 여섯 개쯤 뽑았을 때 기둥이 흔들린다.<br><br>박힌 쇠가 기둥을 지탱하고 있었다.<br>못이 아니라 뼈대였다.<br><br>회랑 전체가 기운다. 기둥이 줄줄이 넘어온다.<br>뽑은 쇠가 손에 가득해서 뛸 수가 없다.`,
        dieText:`놓지 못했다.<br><br>대장장이는 쇠를 놓는 법을 잘 모른다.<br>모아 온 것을 놓는 법은 더 모른다.` },
      good:`뽑았다. 일곱 개. 무게가 상당하다.<br><br>여덟 번째에 손을 멈췄다. 기둥이 미세하게 흔들려서.<br>거기서 그만뒀다. 그만두는 것도 기술이다.`, flag:'pulledIron' },
    { l:'② 어느 것이 좋은지만 본다.', dc:11, kind:'sense', p:450,
      good:`하나만 고른다. 가장 결이 고운 것.<br><br>뽑지 않고 자리만 외웠다.<br>필요할 때 오면 된다.`, flag:'markedIron',
      bad:`보는 중에 하나가 저절로 빠진다.<br><br>발등 옆에 떨어졌다.<br>주우라는 뜻 같기도 하고 아니기도 하다.`, poll:5 }
  ] }
]);

EPIC_SCENES.village.job.smith = [
{ title:'빈 마을 — 식은 화로',
  text:`집집마다 화로가 있다.<br><br>
    전부 식었다. 굴뚝에서는 연기가 나는데 화로는 식었다.<br>
    연기가 어디서 나는지 모르겠다.<br><br>
    화로 하나에 쇠가 얹혀 있다. 녹다 만 채로 굳었다.`,
  opts:[
    { l:'① 다시 녹여 본다.', dc:13, p:600,
      good:`불을 지피고 얹었다. 녹는다.<br><br>녹은 쇠 안에서 뭔가 떠오른다. 작은 고리다.<br>건져 냈다. 반지 같기도 하다.`, flag:'moltenRing',
      bad:`녹지 않는다.<br><br>한참 달궜는데 모양이 그대로다.<br>이 쇠는 녹다 만 게 아니라 원래 이 모양이었다.`, poll:6 },
    { l:'② 굴뚝을 살핀다.', dc:12, kind:'gaze', p:500,
      doom:{ title:'굴뚝', what:'굴뚝에 팔이 끼었습니다', dc:12, sec:60,
        text:`손을 넣어 봤다. 그을음이 없다.<br><br>더 깊이 넣자 뭔가 잡힌다. 따뜻하다.<br>빼려는데 안 빠진다.<br><br>잡힌 게 아니라 잡은 것이다. 저쪽이.<br>천천히 당긴다.`,
        dieText:`어깨까지 들어갔다.<br><br>연기가 나는 이유를 알았다.<br>무언가 계속 타고 있었다. 연료가 떨어지지 않게.` },
      good:`안쪽이 깨끗하다. 그을음 하나 없다.<br><br>불을 땐 적 없는 굴뚝이다.<br>연기는 위에서 내려오고 있었다.`, flag:'cleanFlue' }
  ] }
];

