// 🛡 파수꾼
// ==========================================
EPIC_SCENES.gate.job.warden = (EPIC_SCENES.gate.job.warden || []).concat([

{ title:'성문 — 교대 기록',
  text:`초소 벽에 판이 걸려 있다.<br><br>
    교대 기록이다. 이름과 시각이 줄줄이 적혀 있다.<br>
    마지막 줄에 이름은 있고 교대한 사람이 없다.<br><br>
    그 사람은 아직 근무 중이라는 뜻이다.`,
  opts:[
    { l:'① 이름 아래에 이쪽 이름을 적는다.', dc:12, kind:'bond', p:600,
      good:`적었다. 교대한 것이다.<br><br>적자마자 초소 안 공기가 바뀐다. 가벼워졌다.<br>오래 서 있던 사람이 이제 앉은 것 같다.<br><br>보이지는 않았다. 다만 그렇게 느껴졌다.`, flag:'tookWatch',
      bad:`적으려는데 붓이 마르다.<br><br>손가락에 침을 묻혀 적었다.<br>적은 이름이 번진다. 읽을 수 없게.`, poll:5 },
    { l:'② 기록을 끝까지 읽는다.', dc:13, kind:'gaze', p:650,
      good:`스물셋 명이 교대했다.<br><br>스물넷째만 교대 기록이 없다.<br>이름 옆에 작게 적혀 있다. <span style="color:#d4af37;">"문을 지키다"</span>`, flag:'lastWarden',
      bad:`읽는데 줄이 늘어난다.<br><br>읽는 속도보다 빠르다.<br>마지막 줄에 닿을 수가 없다.`, poll:6 }
  ] },

{ title:'성문 — 순찰',
  text:`정해진 길이 있다.<br><br>
    초소에서 아치까지, 아치에서 담까지, 담에서 초소까지.<br>
    박자가 있다. 발소리가 일정해야 안쪽이 안심한다.<br><br>
    어긋나면 뭔가 눈치챈다.`,
  opts:[
    { l:'① 박자를 지켜 돈다.', mini:'beat', miniOpt:{ p:700, total:12, gap:700 },
      good:`열두 걸음씩 세 번. 어긋나지 않았다.<br><br>도는 동안 아무 일도 안 일어났다.<br>파수꾼의 좋은 근무란 아무 일도 안 일어나는 근무다.`, flag:'patrolled',
      bad:`중간에 엇나갔다.<br><br>발소리가 끊기자 담 너머가 조용해진다.<br>조용해진 건 사라진 게 아니라 멈춘 것이다.` },
    { l:'② 길을 바꿔 돈다.', dc:12, kind:'evade', p:550,
      good:`일부러 다른 길로 돌았다.<br><br>담 뒤에서 뭔가 이쪽을 기다리고 있었다. 빈자리를 발견했다.<br>정해진 길만 도는 파수꾼은 정해진 자리에서 잡힌다.`, flag:'changedRoute',
      bad:`바꾼 길이 막혔다.<br><br>돌아 나오는 데 시간이 걸렸다.<br>그 사이에 아치 쪽에서 소리가 났다.`, poll:6 }
  ] },

{ title:'성문 — 버팀목',
  text:`문을 받칠 것을 세워야 한다.<br><br>
    쓸 만한 것이 여럿 있는데 무게가 맞아야 한다.<br>
    가벼우면 밀리고, 무거우면 문틀이 내려앉는다.<br><br>
    정확히 맞춰야 한다.`,
  opts:[
    { l:'① 무게를 맞춰 괸다.', mini:'scale', miniOpt:{ p:800, target:24, pool:[3,5,6,8,11,13] },
      good:`정확히 맞았다.<br><br>문이 흔들리지 않는다. 밀어 봐도 꿈쩍 안 한다.<br>바깥에서 미는 소리가 났다. 세 번 밀다 그쳤다.`, flag:'braced',
      bad:`어긋났다.<br><br>문틀이 삐걱인다. 받친 것이 서서히 기운다.<br>다시 세울 시간은 없다.` },
    { l:'② 몸으로 받친다.', dc:15, kind:'break', p:700,
      doom:{ title:'받친 문', what:'문에 깔리고 있습니다', dc:14, sec:70,
        text:`등으로 받쳤다.<br><br>밀린다. 신발이 바닥을 긁는다.<br>버티는 만큼 상대도 힘을 더한다.<br><br>무릎이 꺾였다. 문이 어깨를 누른다.<br>파수꾼은 막다 죽는 게 본분이라고 배웠다. 배운 대로 되고 있다.`,
        dieText:`문이 닫혔다.<br><br>안쪽과 바깥쪽 사이에 하나가 남았다.<br>그게 파수꾼의 자리다.` },
      good:`받쳤다. 오래 받쳤다.<br><br>밀던 힘이 먼저 지쳤다.<br>물러나는 소리가 들렸을 때 다리가 풀렸다.`, flag:'heldDoor' }
  ] },

{ title:'성문 — 들여보낼지',
  text:`바깥에서 두드린다.<br><br>
    사람 소리다. 이름을 부른다. 아는 이름이다.<br>
    들여보내면 안 된다는 것도 안다.<br><br>
    파수꾼의 일은 막는 것이다. 누구를 막는지는 정해져 있지 않다.`,
  opts:[
    { l:'① 열지 않는다.', dc:13, p:650,
      good:`열지 않았다.<br><br>두드리는 소리가 오래 이어졌다. 그러다 멎었다.<br>멎고 나서 한참 문 앞에 서 있었다.<br><br>열지 않은 것이 옳았는지는 끝내 모르겠다.`, flag:'keptShut',
      bad:`열지 않으려는데 손이 빗장에 가 있다.<br><br>이름을 불리면 손이 먼저 움직인다.<br>빗장을 반쯤 풀었다가 도로 걸었다.`, poll:7 },
    { l:'② 틈으로 확인한다.', dc:12, kind:'sense', p:600,
      doom:{ title:'틈', what:'문틈으로 붙잡혔습니다', dc:13, sec:65,
        text:`틈으로 내다봤다.<br><br>얼굴이 바로 앞에 있다. 아는 얼굴이다.<br>웃고 있다. 아는 사람은 그렇게 안 웃는다.<br><br>손이 틈으로 들어온다. 얼굴 크기의 틈으로 손이 들어온다.<br>목을 잡았다.`,
        dieText:`틈은 확인하라고 있는 것이 아니다.<br><br>확인하려는 쪽이 확인당하는 자리다.<br>파수꾼이 제일 먼저 배우는 것인데 잊고 있었다.` },
      good:`틈으로 봤다. 아무도 없다.<br><br>두드리는 소리는 계속 난다. 문 자체에서 나고 있었다.<br>확인하고 나니 열 이유가 없어졌다.`, flag:'lookedThrough' },
    { l:'③ 동료에게 판단을 맡긴다.', co:'witness',
      coOpt:{ ask:'문밖에서 부르는 소리가 있습니다. 봐 줄 사람이 필요합니다.', sec:60, p:850,
        text:`혼자 판단하면 나중에 후회한다.`,
        doneText:`누가 왔다. 같이 들었다.<br><br>저쪽도 아는 이름을 들었다고 했다. 다른 이름이었다.<br>같은 소리에서 각자 다른 이름을 들은 것이다.<br><br>둘 다 열지 않기로 했다. 둘이 정하니 후회가 덜했다.`,
        failText:`아무도 오지 않았다.<br><br>혼자 정했다. 열지 않았다.<br>맞는 판단이었는지는 아무도 말해 주지 않는다.` },
      good:`둘이 정했다.`, bad:`혼자 정했다.` }
  ] }
]);

EPIC_SCENES.castle.job.warden = [
{ title:'성 — 지키던 자리',
  text:`성 안에도 초소가 있다.<br><br>
    바깥을 보는 게 아니라 안쪽을 보게 놓여 있다.<br>
    안쪽에 뭔가 가둬 두었다는 뜻이다.<br><br>
    의자에 눌린 자국이 깊다.`,
  opts:[
    { l:'① 앉아서 안쪽을 본다.', dc:13, kind:'gaze', p:650,
      doom:{ title:'안쪽을 보는 자리', what:'자리에서 일어날 수 없습니다', dc:14, sec:70,
        text:`앉았다. 안쪽이 보인다.<br><br>복도 끝 문이 보인다. 저 문을 보라고 놓인 자리다.<br>보고 있으니 일어설 수가 없다.<br><br>일어서면 아무도 안 보게 된다.<br>그 생각이 몸을 눌러앉힌다.`,
        dieText:`앉은 자국이 하나 더 깊어졌다.<br><br>지키는 자리는 비워 두면 안 된다.<br>그래서 비워지지 않는다.` },
      good:`앉아 봤다. 안쪽이 보인다.<br><br>복도 끝에 문이 있고, 그 문은 밖에서만 잠긴다.<br>가두는 쪽이 누구였는지 알겠다.<br><br>일어섰다. 일어서지는 걸 확인하고 나서야 숨이 쉬어졌다.`, flag:'innerWatch' },
    { l:'② 초소 방향을 돌려 놓는다.', dc:12, kind:'break', p:550,
      good:`의자와 판을 바깥 쪽으로 돌렸다.<br><br>무겁다. 오래 고정되어 있었다.<br>돌려놓고 나니 자리가 자리다워졌다.`, flag:'turnedPost',
      bad:`돌리는데 바닥에 박혀 있다.<br><br>뽑으려다 판이 부러졌다.<br>부러진 쪽이 안쪽을 계속 보고 있다.`, poll:7 }
  ] }
];

EPIC_SCENES.village.job.warden = [
{ title:'빈 마을 — 지킬 것이 없는 곳',
  text:`마을에 문이 없다.<br><br>
    담도 없고 울타리도 없다. 지킬 수 있는 구조가 아니다.<br>
    그래서 비었는지도 모른다.<br><br>
    한 집만 문이 잠겨 있다.`,
  opts:[
    { l:'① 그 집 앞을 지킨다.', dc:12, p:600,
      good:`문 앞에 섰다. 한참 섰다.<br><br>아무도 오지 않았고 아무 일도 없었다.<br>파수꾼에게는 그게 성공이다.<br><br>떠날 때 집 안에서 소리가 났다. 고맙다는 소리 같았다.`, flag:'guardedHouse',
      bad:`서 있는데 다리가 굳는다.<br><br>여기 서면 계속 서 있게 되는 자리였다.<br>억지로 발을 뗐다.`, poll:6 },
    { l:'② 동료에게 교대를 청한다.', co:'standin',
      coOpt:{ ask:'이 자리를 잠시 맡아 줄 사람이 필요합니다.', sec:60, p:800,
        text:`혼자 서 있으면 못 떠난다.`,
        doneText:`누가 와서 대신 섰다.<br><br>자세가 어색했다. 파수꾼이 아니니 당연하다.<br>그래도 섰다.<br><br>덕분에 떠날 수 있었다. 교대라는 건 그런 것이다.`,
        failText:`아무도 오지 않았다.<br><br>혼자 떠났다. 떠나는 발이 무거웠다.<br>비운 자리는 오래 마음에 남는다.` },
      good:`교대했다.`, bad:`비우고 떠났다.` }
  ] }
];

EPIC_SCENES.grave.job.warden = [
{ title:'묘지 — 마지막 근무',
  text:`비석 스물셋 앞이다.<br><br>
    파수꾼은 이름을 알 필요가 없다. 수만 맞으면 된다.<br>
    수가 안 맞는다. 자리는 스물넷이다.<br><br>
    한 자리가 비어 있는 건 아직 근무 중이라는 뜻이다.`,
  opts:[
    { l:'① 빈 자리에 선다.', dc:14, kind:'bond', p:750,
      doom:{ title:'빈 자리', what:'자리를 채웠습니다', dc:15, sec:70,
        text:`섰다. 자리가 맞는다.<br><br>정확히 한 사람 폭이다. 발이 자국에 들어맞는다.<br>수가 맞았다. 스물넷.<br><br>발이 가라앉는다. 흙이 무른 게 아니라 자리가 받아들이는 것이다.<br>무릎까지.`,
        dieText:`수가 맞았다.<br><br>파수꾼은 자리를 비우지 않는 사람이다.<br>이 자리는 오래 비어 있었다.` },
      good:`섰다. 잠깐 섰다가 물러났다.<br><br>물러나는 데 힘이 들었다. 자리가 붙잡는 게 아니라 이쪽이 안 떨어졌다.<br><br>수는 안 맞은 채로 뒀다.<br>안 맞는 게 나은 수도 있다.`, flag:'stoodEmpty' }
  ] }
];
;

