EPIC_SCENES.temple.job.priest = (EPIC_SCENES.temple.job.priest || []).concat([

{ title:'신전 — 기도의 박자',
  text:`기도문에는 박자가 있다.<br><br>
    읊는 속도가 정해져 있고, 빠르면 안 듣고 느리면 잊는다.<br>
    벽에 남은 손자국이 그 박자로 찍혀 있다.<br><br>
    맞춰 읊으면 무언가 응답한다. 응답이 무엇인지는 적혀 있지 않다.`,
  opts:[
    { l:'① 박자에 맞춰 읊는다.', mini:'beat', miniOpt:{ p:750, total:12, gap:740 },
      good:`열두 번. 끝까지 어긋나지 않았다.<br><br>마지막 소절에서 촛불이 전부 같은 방향으로 기울었다.<br>바람은 없었다.<br><br>기운 방향을 봤다. 제단 뒤쪽이다. 가 볼 만하다.`, flag:'prayerHeard',
      bad:`중간에 빨라졌다.<br><br>조급한 기도는 기도가 아니라 부탁이다.<br>촛불이 하나씩 꺼졌다. 다 꺼지기 전에 멈췄다.` },
    { l:'② 제물 무게를 맞춘다.', mini:'scale', miniOpt:{ p:700, target:18, pool:[2,4,5,7,9,11] },
      good:`저울이 수평이 된다.<br><br>제단 아래에서 돌 갈리는 소리가 났다.<br>한 칸이 열린다. 안쪽에 마른 꽃이 놓여 있다.<br>아직 향이 남아 있었다.`, flag:'offering',
      bad:`기울었다.<br><br>많이 올리면 욕심이고 적게 올리면 인색하다.<br>정확히 맞춰야 하는데 못 맞췄다.` }
  ] },

{ title:'신전 — 응답한 것',
  text:`기도가 끝나자 대답이 있다.<br><br>
    소리가 아니다. 제단 쪽 공기가 달라졌다.<br>
    사제는 이런 걸 평생에 한 번 겪는다고 배웠다.<br><br>
    대개는 한 번도 못 겪는다.`,
  opts:[
    { l:'① 무릎을 꿇는다.', dc:13, kind:'heal', p:700,
      doom:{ title:'응답', what:'무릎을 꿇은 채 일어나지 못합니다', dc:14, sec:70,
        text:`꿇었다.<br><br>무릎이 바닥에 닿는 순간 편해진다. 아주 편하다.<br>여태 서 있느라 힘들었다는 걸 이제 알았다.<br><br>일어서려는데 이유가 안 떠오른다.<br>여기 있으면 되는데 왜 일어서야 하는지.`,
        dieText:`무릎을 꿇은 자국이 바닥에 여럿 있었다.<br><br>손자국이 겹쳐 있던 이유를 알겠다.<br>오래 만진 게 아니라 오래 붙잡고 있었던 것이다.` },
      good:`꿇었다. 짧게 꿇고 일어섰다.<br><br>일어서는 데 힘이 들었지만 일어섰다.<br>응답은 머무르라는 뜻이 아니라 가라는 뜻이었다.<br><br>그걸 구분하는 게 사제의 일이다.`, flag:'knelt' },
    { l:'② 서서 감사만 표한다.', dc:11, p:550,
      good:`선 채로 고개만 숙였다.<br><br>실례일 수도 있다. 다만 여기서는 그게 맞았다.<br>공기가 도로 평범해졌다.`, flag:'stoodThanks',
      bad:`고개를 숙이는데 목이 안 들린다.<br><br>손으로 들어 올렸다.<br>목이 아니라 다른 게 무거웠던 것 같다.`, poll:7 }
  ] },

{ title:'신전 — 병든 것',
  text:`기둥 뒤에 누가 누워 있다.<br><br>
    숨은 쉰다. 얕게, 오래 끌면서.<br>
    상처는 없다. 병도 아니다. 다만 비어 간다.<br><br>
    사제가 보던 증상이다. 이름은 안 붙는 증상.`,
  opts:[
    { l:'① 이름을 묻고 불러 준다.', dc:12, kind:'bond', p:650,
      good:`이름을 물었다. 대답이 없다.<br><br>그래서 아무 이름이나 붙여 불렀다. 계속 불렀다.<br>세 번째에 눈을 떴다.<br><br>이름이 맞았을 리 없다. 다만 불렸다는 게 중요했던 모양이다.`, flag:'calledSick',
      bad:`불렀는데 이쪽 이름이 나왔다.<br><br>그 사람 입에서 이쪽 이름이 나왔다.<br>부르는 쪽과 불리는 쪽이 바뀌었다.`, poll:8 },
    { l:'② 성수를 먹인다.', dc:13, kind:'heal', p:700,
      good:`받아 온 물을 입에 흘려 넣었다.<br><br>삼킨다. 목이 움직인다.<br>얼굴에 핏기가 돈다. 조금이지만 돈다.<br><br>다 낫지는 않았다. 사제의 일이 다 낫게 하는 일은 아니다.`, flag:'gaveWater',
      bad:`흘려 넣었는데 넘어가지 않는다.<br><br>입 밖으로 도로 나온다. 물이 아니라 다른 것이 되어서.`, poll:9 },
    { l:'③ 동료를 부른다.', co:'call',
      coOpt:{ ask:'옮겨야 할 사람이 있습니다. 드는 손이 필요합니다.', sec:60, p:850,
        text:`혼자 들 수는 없다.`,
        doneText:`둘이 들었다. 가볍다. 사람 무게가 아니다.<br><br>신전 밖으로 옮겨 눕혔다. 햇빛이 드는 자리로.<br>눕히자 숨이 깊어졌다.<br><br>옮기는 것만으로 나아지는 병도 있다.`,
        failText:`혼자 끌었다. 얼마 못 갔다.<br><br>그 자리에 도로 눕혔다.<br>미안하다고 했다. 들었는지는 모르겠다.` },
      good:`옮겼다.`, bad:`옮기지 못했다.` }
  ] },

{ title:'신전 — 꺼지지 않는 초의 안쪽',
  text:`초를 하나 부러뜨려 봤다.<br><br>
    안에 심지가 없다. 대신 가는 뼈가 들어 있다.<br>
    손가락뼈다. 아주 작은.<br><br>
    스물셋 개의 초가 있다.`,
  opts:[
    { l:'① 전부 눕혀 놓는다.', dc:13, kind:'heal', p:750,
      doom:{ title:'눕힌 초', what:'불이 손으로 옮겨붙었습니다', dc:13, sec:65,
        text:`하나씩 눕혔다. 장례를 치르듯이.<br><br>스무 개쯤 눕혔을 때 불이 손에 옮겨붙는다.<br>뜨겁지 않다. 그게 더 나쁘다.<br><br>손끝부터 하얘진다. 밀랍처럼.<br>스물넷째 초가 되려 하고 있다.`,
        dieText:`초가 스물넷이 됐다.<br><br>불꽃은 흔들리는데 몸통은 줄지 않는다.<br>여기 초는 다 그렇다.` },
      good:`전부 눕혔다. 스물셋 개.<br><br>눕히자 하나씩 꺼진다. 순서대로.<br>마지막 하나가 꺼질 때 신전이 어두워졌다.<br><br>어두워진 게 나쁘지 않았다. 오래 밝았던 곳이다.`, flag:'laidCandles' },
    { l:'② 부러뜨린 것만 묻어 준다.', dc:11, p:500,
      good:`제단 아래 흙을 파고 묻었다.<br><br>손바닥만 한 자리다. 표시도 남겼다.<br>하나라도 하는 게 안 하는 것보다 낫다.`, flag:'buriedOne',
      bad:`묻으려고 팠는데 흙 아래가 돌이다.<br><br>파지지 않는다. 묻을 자리가 없는 곳이었다.`, poll:6 }
  ] }
]);

EPIC_SCENES.grave.job.priest = [
{ title:'묘지 — 장례',
  text:`비석 스물셋이 백지다.<br><br>
    이름 없이 묻힌 사람들이다. 장례를 못 치렀다는 뜻이기도 하다.<br>
    사제가 여기 온 이유가 있다면 이것일 것이다.<br><br>
    다만 스물셋 명분의 장례는 하루에 못 치른다.`,
  opts:[
    { l:'① 한 번에 전부 치른다.', dc:14, kind:'heal', p:800,
      good:`한가운데 서서 한 번만 읊었다.<br><br>스물셋을 위해 한 번. 짧게.<br>길게 하면 못 끝낸다. 못 끝내는 장례는 없는 것만 못하다.<br><br>다 읊고 고개를 들었을 때 비석들이 조금 기울어 있었다.<br>고개를 숙인 모양으로.`, flag:'massRite',
      bad:`읊는 중에 숨이 찼다.<br><br>스물셋을 한 번에 담기에는 말이 모자란다.<br>중간에 멈췄다. 멈춘 자리부터는 아무것도 못 했다.`, poll:8 },
    { l:'② 하나씩 치른다.', dc:12, p:700,
      doom:{ title:'하나씩', what:'장례를 멈출 수 없습니다', dc:14, sec:70,
        text:`하나씩 치르기 시작했다.<br><br>열 번째에 알았다. 끝나면 하나가 더 생긴다.<br>치를수록 늘어난다.<br><br>멈추면 치르다 만 것이 되고, 치르다 만 장례는 붙잡는다.<br>무릎이 안 펴진다.`,
        dieText:`스물넷째 비석 앞에서 멈췄다.<br><br>그 비석에는 이름이 있었다.<br>읽고 나서 더는 일어설 수 없었다.` },
      good:`하나씩 치렀다. 짧게, 스물셋 번.<br><br>마지막에 목이 쉬었다. 무릎이 저렸다.<br>다 하고 나서 한참 앉아 있었다.<br><br>사제가 할 수 있는 일은 대개 이런 종류다.`, flag:'eachRite' }
  ] }
];

EPIC_SCENES.lake.job.priest = (EPIC_SCENES.lake.job.priest || []).concat([
{ title:'거울 호수 — 물을 긷는다',
  text:`성수반에 부을 물이 필요하다.<br><br>
    여기 물은 맑다. 다만 비친 것이 이쪽과 다르다.<br>
    퍼 담으면 비친 것도 같이 담길지 모른다.`,
  opts:[
    { l:'① 눈을 감고 긷는다.', dc:12, p:600,
      good:`눈을 감고 담았다.<br><br>수통이 묵직하다. 열어 보니 그냥 물이다.<br>보지 않으면 담기지 않는 것도 있다.`, flag:'blindWater',
      bad:`감고 담았는데 소리가 난다.<br><br>수통 안에서. 아주 작게.<br>버릴까 하다 그대로 들고 갔다.`, poll:7 },
    { l:'② 비친 것을 보며 긷는다.', dc:14, kind:'gaze', p:700,
      doom:{ title:'비친 물', what:'물에 끌려 들어가고 있습니다', dc:13, sec:65,
        text:`비친 얼굴을 보며 담았다.<br><br>손이 물에 닿자 저쪽 손도 닿는다. 마주 잡는 모양으로.<br>잡혔다.<br><br>당긴다. 물이 무릎까지 올라온다.<br>얕은 곳이었는데 깊어졌다.`,
        dieText:`물이 목까지 왔다.<br><br>비친 하늘이 더 맑았다는 게 이제 와서 떠오른다.<br>저쪽이 나은 곳일 수도 있다는 생각이 들었다.<br>그 생각이 든 순간 놓아 버렸다.` },
      good:`보면서 담았다. 저쪽도 담는다.<br><br>수통 둘이 동시에 찼다.<br>이쪽 것만 들고 나왔다. 저쪽 것은 저쪽이 들었다.`, flag:'mirrorWater' }
  ] }
]);

// ==========================================
// 🌿 약초꾼
// ==========================================
EPIC_SCENES.forest.job.herbal = (EPIC_SCENES.forest.job.herbal || []).concat([

{ title:'검은 숲 — 배합',
  text:`딴 것을 달여야 한다.<br><br>
    잎, 뿌리, 껍질. 비율이 틀리면 약이 독이 된다.<br>
    무게로 맞추는 게 확실하다.<br><br>
    저울은 넘어진 나무 아래에 있었다.`,
  opts:[
    { l:'① 무게를 맞춘다.', mini:'scale', miniOpt:{ p:800, target:23, pool:[3,4,6,7,10,13] },
      good:`맞았다.<br><br>달이니 색이 맑다. 김에서 좋은 냄새가 난다.<br>한 모금 마셨다. 목이 시원해지고 손끝이 따뜻해졌다.<br><br>나머지는 병에 담았다. 누구 줄 일이 있을 것이다.`, flag:'brewed',
      bad:`어긋났다.<br><br>색이 탁하다. 냄새가 시다.<br>버렸다. 버린 자리에서 풀이 죽었다.` },
    { l:'② 별 모양으로 난 잎을 순서대로 딴다.', mini:'star', miniOpt:{ p:750, n:6, sec:16 },
      good:`밝은 순서대로 땄다.<br><br>순서가 맞으면 잎이 마르지 않는다. 오래 간다.<br>배운 것을 써먹은 건 오랜만이다.`, flag:'starLeaf',
      bad:`순서가 틀렸다.<br><br>딴 잎이 손안에서 시든다. 검게 오그라든다.<br>털어 버렸다.` }
  ] },

{ title:'검은 숲 — 모르는 풀',
  text:`처음 보는 풀이 있다.<br><br>
    책에도 없고 스승도 말해 준 적 없다.<br>
    약초꾼이 모르는 풀을 만나는 건 흔한 일이 아니다.<br><br>
    알려면 씹어 보는 수밖에 없다.`,
  opts:[
    { l:'① 조금만 씹는다.', dc:13, kind:'heal', p:650,
      doom:{ title:'씹은 것', what:'독이 퍼지고 있습니다', dc:14, sec:65,
        text:`혀끝에 아주 조금 댔다.<br><br>단맛이 난다. 약초에 단맛이 나면 대개 나쁘다.<br>뱉었는데 이미 늦었다.<br><br>목이 조인다. 숨이 반만 들어온다.<br>해독할 풀이 뭔지 아는데, 손이 안 움직인다.`,
        dieText:`약초꾼은 독을 제일 잘 아는 사람이다.<br><br>제일 잘 아는 사람이 제일 자주 당한다.<br>알면 시험해 보고 싶어지기 때문이다.` },
      good:`혀끝에 댔다. 쓰다. 아주 쓰다.<br><br>쓴 것은 대개 약이다. 단 것이 대개 독이고.<br>뱉고 나서 한 줌 챙겼다.<br><br>이름은 아직 없다. 나중에 붙이면 된다.`, flag:'newHerb' },
    { l:'② 안 건드린다.', dc:10, p:400,
      good:`보기만 하고 지나쳤다.<br><br>모르는 것을 안 건드리는 게 오래 사는 법이다.<br>스승이 그것만은 확실히 가르쳐 줬다.`, flag:'leftHerb',
      bad:`지나치는데 옷자락에 씨가 붙었다.<br><br>털어도 안 떨어진다. 파고든다.<br>옷을 조금 잘라 냈다.`, poll:6 }
  ] },

{ title:'검은 숲 — 덩굴',
  text:`덩굴이 길을 덮었다.<br><br>
    가시가 없다. 대신 끈적하다.<br>
    지나가려면 헤쳐야 하고, 헤치면 달라붙는다.<br><br>
    이런 것도 약재가 되긴 한다.`,
  opts:[
    { l:'① 잘라 가며 지난다.', dc:12, p:550,
      doom:{ title:'덩굴', what:'덩굴에 감겼습니다', dc:13, sec:65,
        text:`자를수록 늘어난다.<br><br>자른 자리에서 둘이 난다. 둘을 자르면 넷이 난다.<br>팔에 감기기 시작했다.<br><br>당기는 게 아니라 조인다. 천천히, 계속.<br>칼을 든 손부터 감겼다.`,
        dieText:`덩굴이 목까지 왔다.<br><br>약재가 되는 것들은 대개 사람을 먹고 자란다.<br>그 사실을 책에서는 안 가르친다.` },
      good:`자르지 않고 들어 올려 지났다.<br><br>덩굴은 자르면 화를 낸다. 들어 주면 비켜 준다.<br>지나가서 뒤를 보니 도로 내려와 있었다.`, flag:'liftedVine' },
    { l:'② 수액을 받는다.', dc:13, p:600,
      good:`줄기에 칼집을 냈다. 수액이 흐른다.<br><br>받아서 냄새를 맡았다. 상처에 좋은 냄새다.<br>병에 담았다. 덩굴은 화내지 않았다.`, flag:'sap',
      bad:`칼집을 내자 덩굴 전체가 떤다.<br><br>수액이 아니라 다른 게 나온다. 붉고 따뜻하다.<br>병을 도로 넣었다.`, poll:8 }
  ] },

{ title:'검은 숲 — 나눠 쓴다',
  text:`달인 약이 한 병이다.<br><br>
    혼자 쓰면 충분하고, 나누면 모자란다.<br>
    약초꾼은 대개 나눈다. 그래서 늘 모자란다.`,
  opts:[
    { l:'① 동료에게 건넨다.', co:'handoff',
      coOpt:{ ask:'달인 약이 있습니다. 필요한 사람이 있으면 오십시오.', sec:60, p:900,
        text:`쓸 사람에게 가는 게 약이다.`,
        doneText:`누가 왔다. 어디가 아픈지는 안 물었다.<br><br>병을 건넸다. 받아 마시더니 병을 돌려줬다.<br>절반 남겨서.<br><br>나눠 쓰라고 남긴 것이다. 그 절반이 오래 갔다.`,
        failText:`아무도 오지 않았다.<br><br>혼자 마셨다. 충분했다.<br>충분한데 개운하지가 않았다.` },
      good:`나눴다.`, bad:`혼자 마셨다.`, flag:'sharedBrew' }
  ] }
]);

EPIC_SCENES.village.job.herbal = [
{ title:'빈 마을 — 약장',
  text:`한 집에 약장이 있다.<br><br>
    서랍이 스물넷이다. 이름표가 붙어 있고 전부 아는 약재다.<br>
    스물셋은 비어 있다.<br><br>
    하나만 차 있다. 이름표가 떨어져 나갔다.`,
  opts:[
    { l:'① 열어 본다.', dc:12, kind:'sense', p:600,
      good:`말린 것이 들어 있다. 만져 보니 뿌리다.<br><br>냄새를 맡았다. 숲 가운데서 캔 것과 같은 냄새다.<br>여기 살던 약초꾼도 그걸 캤던 것이다.<br><br>조금 덜어 왔다. 남겨 두는 것도 예의다.`, flag:'oldStock',
      bad:`열었는데 비어 있다.<br><br>차 있는 줄 알았는데 서랍이 깊었던 것뿐이다.<br>바닥에 가루가 조금 남아 있다.`, poll:5 },
    { l:'② 이름표를 다시 붙인다.', dc:11, p:500,
      good:`알아본 대로 이름을 적어 붙였다.<br><br>스물넷 개가 다 이름을 갖게 됐다.<br>비어 있는 것도 이름은 있어야 한다.`, flag:'labeled',
      bad:`적으려는데 이름이 안 떠오른다.<br><br>손에 쥔 게 뭔지 알겠는데 부를 말이 없다.<br>빈 이름표를 도로 붙였다.`, poll:6 }
  ] }
];

EPIC_SCENES.lake.job.herbal = (EPIC_SCENES.lake.job.herbal || []).concat([
{ title:'거울 호수 — 물가의 뿌리',
  text:`물가에 뿌리가 드러나 있다.<br><br>
    물이 씻어 낸 것이다. 굵고 희다.<br>
    당기면 빠질 것 같다.<br><br>
    다만 물속으로 얼마나 이어졌는지는 안 보인다.`,
  opts:[
    { l:'① 당겨 본다.', dc:13, p:650,
      doom:{ title:'뿌리', what:'물속으로 끌려가고 있습니다', dc:13, sec:65,
        text:`당겼다. 딸려 나온다. 계속 나온다.<br><br>팔 길이, 사람 길이, 그 이상.<br>끝이 없다.<br><br>어느 순간 당기는 쪽이 바뀌었다.<br>손에 감긴 뿌리가 물 쪽으로 끌어당긴다.`,
        dieText:`발이 물에 들어갔다.<br><br>드러난 뿌리는 씻겨 나온 게 아니라 내밀어 둔 것이었다.<br>낚싯줄처럼.` },
      good:`조금만 당겼다.<br><br>한 뼘쯤 나온 데서 잘랐다. 더 당기면 안 될 것 같아서.<br>자른 자리에서 맑은 물이 나왔다. 약이 된다.`, flag:'rootCut' }
  ] }
]);

// ==========================================
// 🕯 산파
// ==========================================
EPIC_SCENES.village.job.midwife = (EPIC_SCENES.village.job.midwife || []).concat([

{ title:'빈 마을 — 호흡',
  text:`숨을 맞춰야 한다.<br><br>
    산파가 먼저 박자를 잡고, 산모가 따라온다.<br>
    빠르면 지치고 느리면 힘이 안 실린다.<br><br>
    손을 잡고 박자를 낸다.`,
  opts:[
    { l:'① 박자를 잡아 준다.', mini:'beat', miniOpt:{ p:800, total:12, gap:820 },
      good:`하나, 둘. 하나, 둘.<br><br>손을 통해 박자가 전해진다. 따라온다.<br>열두 번째에 숨이 깊어졌다.<br><br>산파가 하는 일의 절반은 이것이다. 숨을 나눠 주는 것.`, flag:'breathHeld',
      bad:`박자가 엇나갔다.<br><br>산모가 먼저 지친다. 숨이 얕아진다.<br>다시 잡는 데 시간이 걸렸다. 시간이 없는 일인데.` },
    { l:'② 탕약을 지어 먹인다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[3,5,6,8,9,12] },
      good:`분량이 맞았다.<br><br>먹이자 숨이 고르게 돌아온다.<br>약이 듣는 걸 보는 건 몇 번을 봐도 좋다.`, flag:'gaveTonic',
      bad:`진하게 지었다.<br><br>먹이자 기침을 한다. 게워 낸다.<br>약이 독이 되는 건 분량 하나 차이다.` }
  ] },

{ title:'빈 마을 — 산모가 아닌 것',
  text:`다른 집에서도 숨소리가 난다.<br><br>
    같은 소리다. 짧고 가쁜 숨.<br>
    집집마다 난다. 스물셋 집에서.<br><br>
    전부 받아 낼 수는 없다.`,
  opts:[
    { l:'① 가장 가까운 집으로 간다.', dc:12, p:650,
      doom:{ title:'다른 집', what:'집 안에 붙잡혔습니다', dc:14, sec:70,
        text:`들어갔다. 누워 있는 것이 있다.<br><br>사람 모양인데 배가 움직인다. 안쪽에서 미는 것처럼.<br>다가갔다.<br><br>손이 올라와 팔을 잡는다. 힘이 세다.<br>받아 달라는 자세가 아니다. 끌어당기는 자세다.`,
        dieText:`배가 열린다.<br><br>산파는 처음 우는 소리를 가장 많이 들은 사람이다.<br>여기서 난 소리는 처음 듣는 소리였다.` },
      good:`들어갔다. 아무도 없다.<br><br>숨소리만 있다. 방 한가운데서, 아무것도 없는 자리에서.<br>물러 나왔다.<br><br>없는 것을 받아 낼 수는 없다. 그건 산파의 일이 아니다.`, flag:'emptyBirth' },
    { l:'② 전부 무시하고 처음 집으로 돌아간다.', dc:11, p:550,
      good:`돌아갔다. 소리가 등 뒤에서 계속 났다.<br><br>산파는 한 번에 하나만 받는다. 그게 규칙이다.<br>규칙을 지키는 게 여기서는 살아남는 방법이기도 했다.`, flag:'stayedOne',
      bad:`돌아가는데 소리가 따라온다.<br><br>집집마다 문이 열린다. 순서대로.<br>뛰었다.`, poll:8 }
  ] },

{ title:'빈 마을 — 받아 낸 뒤',
  text:`받아 냈다.<br><br>
    울었고, 씻겼고, 감쌌다.<br>
    이제 산모에게 안겨 주면 끝난다.<br><br>
    안겨 주려는데 손이 안 펴진다.`,
  opts:[
    { l:'① 억지로 건넨다.', dc:13, kind:'heal', p:750,
      doom:{ title:'놓지 못한 손', what:'아이를 놓지 못하고 있습니다', dc:14, sec:70,
        text:`손가락을 하나씩 폈다.<br><br>펴지지 않는다. 쥐고 있는 게 아니라 붙은 것이다.<br>따뜻하다. 놓기 싫다는 마음이 어디서 왔는지 모르겠다.<br><br>산모가 손을 내민다. 기다리고 있다.<br>못 건네고 있다.`,
        dieText:`처음 받은 것을 놓지 못한 산파가 여럿 있었다고 들었다.<br><br>그 말이 무슨 뜻인지 여태 몰랐다.<br>이제 알겠다.` },
      good:`폈다. 힘을 줘서 폈다.<br><br>건넸다. 산모가 받는다. 받는 손이 떨린다.<br>둘 다 떨렸다.<br><br>산파의 일은 받는 것이 아니라 건네는 것으로 끝난다.`, flag:'handedOver' },
    { l:'② 동료를 부른다.', co:'standin',
      coOpt:{ ask:'손이 안 펴집니다. 대신 건네 줄 사람이 필요합니다.', sec:55, p:900,
        text:`혼자서는 못 놓는다.`,
        doneText:`누가 와서 손가락을 하나씩 폈다.<br><br>말없이 폈다. 다 펴고 나서 대신 건넸다.<br>건네는 걸 옆에서 봤다.<br><br>보는 것만으로도 끝난 셈이 됐다.`,
        failText:`아무도 오지 않았다.<br><br>혼자 폈다. 손톱이 부러졌다.<br>건네고 나서 한참 손을 쥐었다 폈다 했다.` },
      good:`건넸다.`, bad:`혼자 폈다.` }
  ] },

{ title:'빈 마을 — 이름을 묻는다',
  text:`산모가 묻는다.<br><br>
    아이 이름이 아니라 이쪽 이름을.<br>
    받아 준 사람 이름을 아이에게 알려 주려는 것이다.<br><br>
    여기서 이름을 말하는 게 어떤 일인지는 알고 있다.`,
  opts:[
    { l:'① 말해 준다.', dc:14, kind:'bond', p:800,
      doom:{ title:'말한 이름', what:'이름이 옮겨 갔습니다', dc:15, sec:70,
        text:`말했다.<br><br>산모가 받아 적는다. 손가락으로, 아이 손바닥에.<br>적는 동안 이쪽 이름이 가벼워진다.<br><br>불러 봐도 대답할 사람이 없다.<br>이름이 저쪽으로 갔다.`,
        dieText:`아이가 이름을 가졌다.<br><br>이름은 하나씩만 있는 것이었다.<br>준 쪽은 없어진다.` },
      good:`말했다.<br><br>산모가 고개를 끄덕인다. 적지는 않았다.<br>외우겠다고 했다. 외우는 편이 안전하다는 걸 아는 사람이었다.<br><br>나오면서 이름을 한 번 불러 봤다. 아직 이쪽 것이었다.`, flag:'gaveName' },
    { l:'② 다른 이름을 말한다.', dc:12, kind:'evade', p:700,
      good:`아무 이름이나 댔다.<br><br>산모가 웃는다. 알고 있으면서 받아 적는다.<br>여기서는 그게 예의라는 걸 서로 알고 있었다.`, flag:'falseName',
      bad:`댔는데 입에서 진짜 이름이 나왔다.<br><br>고치려는데 이미 적혔다.<br>적힌 걸 지울 수는 없다.`, poll:9 },
    { l:'③ 아이 이름을 지어 준다.', dc:13, p:750,
      good:`이쪽 이름 대신 아이 이름을 지어 줬다.<br><br>산모가 좋아했다. 소리 내어 몇 번 불렀다.<br>부를수록 아이가 또렷해진다. 정말로 또렷해졌다.<br><br>이름을 주는 쪽이 되는 건 처음이었다.`, flag:'namedChild',
      bad:`지어 주려는데 떠오르는 게 이쪽 이름뿐이다.<br><br>다른 이름이 하나도 생각나지 않는다.<br>결국 말 안 했다.`, poll:7 }
  ] }
]);

EPIC_SCENES.temple.job.midwife = [
{ title:'신전 — 아이의 자리',
  text:`제단 아래 관이 있다.<br><br>
    작다. 아이 것이다.<br>
    눌린 자국이 있는데 비어 있다.<br><br>
    산파는 처음 우는 소리를 듣는 사람이지 이런 걸 보는 사람이 아니다.`,
  opts:[
    { l:'① 관을 덮어 준다.', dc:11, kind:'heal', p:600,
      good:`뚜껑이 없어서 겉옷을 덮었다.<br><br>덮고 나니 마음이 덜 무겁다.<br>비어 있는 것을 덮는 데도 의미가 있다.`, flag:'coveredCoffin',
      bad:`덮으려는데 옷이 안 놓인다.<br><br>손에서 떠나지 않는다.<br>세 번 시도하고 그만뒀다.`, poll:6 },
    { l:'② 안쪽 자국을 살핀다.', dc:13, kind:'sense', p:650,
      doom:{ title:'눌린 자국', what:'관 속에서 손이 잡혔습니다', dc:13, sec:60,
        text:`손을 넣어 자국을 짚어 봤다.<br><br>따뜻하다. 방금까지 누워 있던 온도다.<br>짚은 손이 잡힌다. 작은 손이다.<br><br>세게 쥔다. 아이 힘이 아니다.<br>빼려는데 안 빠진다.`,
        dieText:`관은 작았다.<br><br>작은데도 들어갈 자리가 있었다.<br>산파가 마지막으로 받은 것은 자기 자신이었다.` },
      good:`자국이 작다. 갓난아이 크기다.<br><br>손을 모은 자세로 누워 있었다.<br>일어난 게 아니라 옮겨진 것 같다. 자국이 흐트러지지 않았다.<br><br>어디로 옮겨졌는지는 모르겠다.`, flag:'smallPrint' }
  ] }
];
;

