// ==========================================
// 🎣 낚시꾼
// ==========================================
EPIC_SCENES.lake.job.fisher = (EPIC_SCENES.lake.job.fisher || []).concat([

{ title:'거울 호수 — 줄을 당기는 법',
  text:`입질이 온다.<br><br>
    당기는 박자가 있다. 쉬었다 당기고, 쉬었다 당기고.<br>
    한 번에 채면 줄이 끊어지고, 놓치면 달아난다.<br><br>
    손목으로 세는 박자다.`,
  opts:[
    { l:'① 박자에 맞춰 당긴다.', mini:'beat', miniOpt:{ p:800, total:10, gap:780 },
      good:`열 번. 줄이 버텼다.<br><br>올라온 것은 크지 않다. 다만 무겁다.<br>비늘이 젖어 있지 않다. 물속에 있었는데 마른 채로 올라왔다.<br><br>바늘을 빼 주자 한 번 몸을 뒤집고 도로 들어갔다.`, flag:'pulledRight',
      bad:`한 번 세게 챘다.<br><br>줄이 끊어진다. 끊어진 자리가 깨끗하다.<br>물어뜯은 게 아니라 잘린 것이다. 저쪽이 놓아준 것이다.` },
    { l:'② 봉돌 무게를 맞춘다.', mini:'scale', miniOpt:{ p:700, target:17, pool:[2,3,5,6,9,11] },
      good:`정확히 맞았다.<br><br>찌가 수면에 반쯤 잠긴다. 딱 좋은 깊이다.<br>기다릴 준비가 됐다. 낚시꾼에게 준비란 그게 전부다.`, flag:'rigged',
      bad:`무겁다. 찌가 가라앉는다.<br><br>당겨 올리니 바닥 것이 딸려 온다.<br>바닥에 있어야 할 것이 아니었다.` }
  ] },

{ title:'거울 호수 — 낚인 쪽',
  text:`줄이 팽팽하다.<br><br>
    당기는데 안 온다. 바위에 걸린 게 아니다. 살아 있는 저항이다.<br>
    발에 힘을 주고 버텼다.<br><br>
    힘이 비슷하면 오래 간다. 오래 가면 지는 쪽이 생긴다.`,
  opts:[
    { l:'① 끝까지 버틴다.', dc:14, kind:'luck', p:750,
      doom:{ title:'끌려 들어간다', what:'물속으로 끌려가고 있습니다', dc:13, sec:65,
        text:`버텼다. 발이 미끄러진다.<br><br>흙이 아니라 물가 풀이다. 젖어서 미끄럽다.<br>무릎까지 들어갔다.<br><br>낚싯대를 놓으면 된다. 놓으면 되는데 손이 안 펴진다.<br>낚시꾼의 손은 놓는 법을 늦게 배운다.`,
        dieText:`허리까지 들어갔다.<br><br>물속이 따뜻하다. 위보다 따뜻하다.<br>낚은 쪽과 낚인 쪽이 바뀌는 데는 한순간이면 된다.` },
      good:`버텼다. 오래 버텼다.<br><br>먼저 지친 건 저쪽이었다.<br>끌어 올리니 아무것도 없다. 바늘만 돌아왔다.<br><br>바늘이 휘어 있다. 안쪽으로.`, flag:'outlasted' },
    { l:'② 줄을 놓는다.', dc:10, p:450,
      good:`놓았다. 낚싯대가 물로 끌려간다.<br><br>순식간에 사라졌다. 저렇게 빨랐으면 버텼어도 소용없었다.<br>놓기를 잘했다.`, flag:'letGo',
      bad:`놓으려는데 줄이 손가락에 감겼다.<br><br>풀기 전에 한 번 당겨졌다.<br>손바닥이 찢어졌다.`, poll:8 }
  ] },

{ title:'거울 호수 — 오래 앉은 자리',
  text:`눌린 자국에 앉아 있다.<br><br>
    편하다. 아주 편하다.<br>
    일어설 생각이 잘 안 든다. 기다리는 게 일이니 당연한데,<br>
    당연한 게 이상하게 느껴진다.<br><br>
    해가 없는데도 시간이 가는 게 느껴진다.`,
  opts:[
    { l:'① 일어선다.', dc:12, kind:'evade', p:600,
      doom:{ title:'자리', what:'자리에서 일어나지 못합니다', dc:13, sec:65,
        text:`일어서려는데 다리가 안 펴진다.<br><br>저린 게 아니다. 자국에 맞아 들어간 것이다.<br>엉덩이가 자국이고 자국이 엉덩이다.<br><br>얼마나 앉아 있었는지 모르겠다.<br>여기 자국을 만든 사람도 그랬을 것이다.`,
        dieText:`자국이 한 겹 깊어졌다.<br><br>다음에 오는 낚시꾼이 앉기 좋게.` },
      good:`허벅지를 두드려 감각을 되살리고 일어섰다.<br><br>일어서니 자국이 그대로다. 이쪽 모양이 아니다.<br>앉았는데도 이쪽 자국은 안 남았다.<br><br>그게 다행인지 아닌지 모르겠다.`, flag:'gotUp' },
    { l:'② 조금 더 앉아 있는다.', dc:13, kind:'luck', p:700,
      good:`앉아 있었다. 오래.<br><br>기다린 값은 있었다. 물 밑에서 빛이 지나갔다.<br>줄지어, 천천히. 등불을 든 것들이었다.<br><br>세어 보니 스물셋이다.`, flag:'sawLights',
      bad:`앉아 있는데 옆에 누가 앉는다.<br><br>고개를 안 돌렸다. 돌리면 안 될 것 같았다.<br>한참 뒤에 일어섰다. 옆자리에 자국이 하나 더 있었다.`, poll:8 }
  ] },

{ title:'거울 호수 — 나눠 먹는다',
  text:`낚은 것이 있다.<br><br>
    혼자 먹으면 남고, 나누면 모자란다.<br>
    낚시꾼은 대개 나눈다. 다음에 또 낚으면 되니까.`,
  opts:[
    { l:'① 동료를 부른다.', co:'handoff',
      coOpt:{ ask:'낚은 것이 있습니다. 나눠 먹을 사람이 필요합니다.', sec:60, p:900,
        text:`혼자 먹기에는 많다.`,
        doneText:`누가 왔다. 구워서 나눠 먹었다.<br><br>맛이 없었다. 여기 것이 맛있을 리 없다.<br>그래도 둘이 먹으니 먹을 만했다.<br><br>먹고 나서 둘 다 배가 불렀다. 양이 늘어난 것처럼.`,
        failText:`아무도 오지 않았다.<br><br>혼자 먹었다. 한 입 먹고 말았다.<br>나머지는 물에 돌려보냈다.` },
      good:`나눴다.`, bad:`혼자 먹었다.`, flag:'sharedCatch' }
  ] }
]);

EPIC_SCENES.road.job.fisher = [
{ title:'끊긴 길 — 안개를 낚는다',
  text:`끊긴 자리에 안개가 고여 있다.<br><br>
    평평하다. 물처럼.<br>
    낚싯대를 드리우면 어떻게 될지 궁금해진다.<br><br>
    낚시꾼의 나쁜 버릇이다.`,
  opts:[
    { l:'① 드리운다.', dc:13, kind:'luck', p:700,
      doom:{ title:'안개 속', what:'안개에서 뭔가 물었습니다', dc:14, sec:65,
        text:`드리웠다. 곧바로 물었다.<br><br>당긴다. 무겁다. 물고기 무게가 아니다.<br>올라오는 게 아니라 이쪽이 끌려 내려간다.<br><br>발이 길 끝에 걸려 있다. 반쯤 나가 있다.<br>안개가 발목을 감싼다. 따뜻하다.`,
        dieText:`안개에 낚이는 것이 뭔지 알게 됐다.<br><br>여기서는 낚싯대를 들면 이쪽이 미끼다.` },
      good:`드리웠다. 한참 아무 반응이 없다.<br><br>거두려는데 찌가 한 번 까딱했다.<br>거기서 그만뒀다. 물리기 전에 거두는 게 낫다.<br><br>바늘에 안개가 조금 묻어 있었다. 병에 담았다.`, flag:'fogBait' },
    { l:'② 깊이만 재 본다.', dc:11, p:450,
      good:`봉돌만 내려 봤다. 줄이 계속 풀린다.<br><br>끝이 없다. 바닥이 없는 자리였다.<br>줄을 감아 올렸다. 봉돌이 안 돌아왔다.`, flag:'noBottom',
      bad:`재는데 줄이 저절로 풀린다.<br><br>손을 놓지 않았는데 풀린다.<br>끊었다.`, poll:6 }
  ] }
];

EPIC_SCENES.forest.job.fisher = [
{ title:'검은 숲 — 마른 강',
  text:`강바닥이 있다.<br><br>
    물이 없다. 돌만 남았고 돌이 전부 젖어 있다.<br>
    물이 마른 게 아니라 잠깐 자리를 비운 것 같다.<br><br>
    돌 사이에 비늘이 끼어 있다.`,
  opts:[
    { l:'① 비늘을 챙긴다.', dc:11, p:500,
      good:`집었다. 손바닥만 하다. 크다.<br><br>빛에 비추니 무늬가 있다. 글자 같기도 하다.<br>주머니에 넣었다.`, flag:'bigScale',
      bad:`집는 순간 젖은 돌이 움직인다.<br><br>돌이 아니었다. 젖은 이유가 있었다.<br>손을 뗐다.`, poll:7 },
    { l:'② 물이 어디 갔는지 찾는다.', dc:13, kind:'sense', p:650,
      good:`바닥의 기울기를 따라갔다.<br><br>숲 안쪽으로 이어진다. 둥근 공터 쪽이다.<br>물이 그리로 갔다는 뜻이다. 아니면 그쪽이 마셨거나.`, flag:'driedRiver',
      bad:`따라가다 바닥이 젖어든다.<br><br>물이 돌아오는 중이었다.<br>발목까지 찼을 때 빠져나왔다.`, poll:8 }
  ] }
];

// ==========================================
// 🎲 도박사
// ==========================================
EPIC_SCENES.market.job.gambler = (EPIC_SCENES.market.job.gambler || []).concat([

{ title:'장터 — 패를 돌린다',
  text:`이번에는 이쪽이 돌리는 차례다.<br><br>
    돌리는 박자가 있다. 빠르면 의심받고 느리면 눈치챈다.<br>
    여섯에게 한 장씩, 여섯 바퀴.<br><br>
    박자만 지키면 아무도 안 본다.`,
  opts:[
    { l:'① 박자를 지켜 돌린다.', mini:'beat', miniOpt:{ p:800, total:12, gap:640 },
      good:`열두 번. 손이 흔들리지 않았다.<br><br>돌리면서 한 장을 남겼다. 아무도 못 봤다.<br>남긴 패를 나중에 봤더니 백지였다.<br><br>백지를 숨긴 셈이다. 그래도 숨긴 건 숨긴 것이다.`, flag:'dealt',
      bad:`중간에 손이 미끄러졌다.<br><br>한 장이 뒤집혀 떨어졌다. 백지다.<br>여섯이 동시에 그 패를 봤다. 그리고 이쪽을 봤다.` },
    { l:'② 판돈을 나눠 건다.', mini:'scale', miniOpt:{ p:750, target:22, pool:[3,4,7,8,10,12] },
      good:`정확히 나눠 걸었다.<br><br>어느 쪽이 이겨도 본전 이상이다. 도박사가 아니라 장부쟁이가 하는 짓이다.<br>그래도 이겼다.`, flag:'hedged',
      bad:`계산이 어긋났다.<br><br>양쪽 다 조금씩 잃는 자리에 걸었다.<br>도박에서 제일 나쁜 자리다.` }
  ] },

{ title:'장터 — 끝나지 않는 판',
  text:`한 판이 끝나면 다음 판이 시작된다.<br><br>
    끝난 적이 없는 것 같다. 앉은 사람도 안 바뀐다.<br>
    이기든 지든 다음 판이 온다.<br><br>
    일어설 수는 있다. 일어서면 그동안 딴 게 사라진다고 한다.`,
  opts:[
    { l:'① 일어선다.', dc:12, kind:'evade', p:600,
      good:`일어섰다. 주머니를 확인하니 그대로다.<br><br>사라진다는 말은 거짓이었다.<br>거짓말로 앉혀 두는 판이었던 것이다.<br><br>도박사가 제일 먼저 배우는 건 일어서는 때를 아는 것이다.`, flag:'stoodUp',
      bad:`일어서는데 다리가 안 펴진다.<br><br>의자가 아니라 이쪽이 문제다.<br>한참 걸려 일어섰다.`, poll:7 },
    { l:'② 한 판만 더 한다.', dc:14, kind:'luck', p:800,
      doom:{ title:'한 판만 더', what:'판에서 일어날 수 없습니다', dc:14, sec:70,
        text:`한 판만 더. 그 말을 몇 번째 하는지 모르겠다.<br><br>이겼다. 그래서 한 판 더. 졌다. 그래서 한 판 더.<br>주머니가 가벼워지고 손이 무거워진다.<br><br>걸 게 없어졌다. 여섯이 이쪽을 본다.<br>아직 걸 게 하나 남았다는 눈빛으로.`,
        dieText:`마지막으로 건 것이 뭐였는지는 기억이 안 난다.<br><br>다만 판이 계속되고 있고, 이쪽이 앉아 있다.<br>일곱 명이 됐다.` },
      good:`한 판 더 했다. 이겼다.<br><br>이기고 나서 곧바로 일어섰다.<br>손이 떨렸다. 떨리는 걸 보고 그만둘 때를 알았다.`, flag:'oneMore' }
  ] },

{ title:'장터 — 빚',
  text:`걸 게 없어졌을 때 방법이 있다.<br><br>
    빌리면 된다. 여기서는 빌려주는 쪽이 늘 있다.<br>
    조건은 나중에 말해 준다고 한다.<br><br>
    나중에 말해 주는 조건이 좋았던 적은 없다.`,
  opts:[
    { l:'① 빌린다.', dc:15, kind:'luck', p:900,
      doom:{ title:'빌린 것', what:'갚을 것을 요구받고 있습니다', dc:15, sec:70,
        text:`빌렸다. 손에 쥐여 준 것이 묵직하다.<br><br>그 판에서 잃었다.<br>빌려준 쪽이 손을 내민다. 조건을 말해 준다.<br><br>포인트가 아니다. 시간도 아니다.<br>이름이라고 했다.`,
        dieText:`이름을 줬다.<br><br>빚은 갚았다. 갚고 나니 부를 것이 없다.<br>도박사는 늘 마지막에 자기를 건다.` },
      good:`빌렸다. 그 판에서 이겼다.<br><br>곧바로 갚았다. 갚는 게 빠를수록 조건이 싸진다.<br>빌려준 쪽이 아쉬워했다. 아쉬워하는 걸 보니 잘한 것이다.`, flag:'repaid' },
    { l:'② 안 빌린다.', dc:10, p:400,
      good:`고개를 저었다.<br><br>빌려주려던 손이 거둬진다. 서운해하지 않는다.<br>다음 사람에게 내밀 것이다.`, flag:'refusedLoan',
      bad:`거절했는데 이미 주머니에 들어와 있다.<br><br>언제 넣었는지 모르겠다.<br>돌려주려 했지만 받지 않는다.`, poll:9 }
  ] },

{ title:'장터 — 대신 걸어 준다',
  text:`혼자 걸면 혼자 잃는다.<br><br>
    둘이 걸면 반씩 잃고 반씩 딴다.<br>
    도박사는 그걸 알면서도 혼자 건다. 나누기 싫어서.<br><br>
    여기서는 나누는 편이 나을 것 같다.`,
  opts:[
    { l:'① 동료에게 반을 맡긴다.', co:'handoff',
      coOpt:{ ask:'판이 벌어졌습니다. 반을 맡아 줄 사람이 필요합니다.', sec:60, p:900,
        text:`둘이 걸면 한쪽이 잃어도 다른 쪽이 남는다.`,
        doneText:`반을 넘겼다. 그쪽이 다른 자리에 걸었다.<br><br>이쪽이 졌고 저쪽이 이겼다.<br>합치니 본전보다 나았다.<br><br>도박사에게 본전은 지는 것인데, 이번엔 그렇지 않았다.`,
        failText:`아무도 오지 않았다.<br><br>혼자 전부 걸었다. 반쯤 잃었다.<br>나눴으면 덜 잃었을 것이다.` },
      good:`나눠 걸었다.`, bad:`혼자 걸었다.`, flag:'splitBet' }
  ] }
]);

EPIC_SCENES.castle.job.gambler = [
{ title:'성 — 값이 매겨진 장부',
  text:`장부가 걸려 있다.<br><br>
    물건 사이에 사람이 섞여 있고 값이 매겨져 있다.<br>
    값이 싸다. 아주 싸다.<br><br>
    도박사는 값을 보면 내기부터 생각한다.`,
  opts:[
    { l:'① 값을 올려 적는다.', dc:13, kind:'bond', p:700,
      good:`숫자 앞에 획을 하나 더 그었다.<br><br>값이 열 배가 됐다.<br>장부가 한 번 떨린다. 인정된 것이다.<br><br>비싸진 것은 함부로 못 쓴다. 그게 요령이다.`, flag:'raisedPrice',
      bad:`고치는데 먹이 안 먹는다.<br><br>쓴 자리가 곧바로 마른다. 원래 숫자로 돌아간다.<br>정해진 값이었다.`, poll:7 },
    { l:'② 이쪽 이름을 찾아본다.', dc:12, kind:'gaze', p:650,
      doom:{ title:'장부의 이름', what:'값이 매겨졌습니다', dc:14, sec:70,
        text:`찾았다. 마지막 장에 있다.<br><br>값이 안 적혀 있다. 빈칸이다.<br>보고 있으니 숫자가 떠오른다. 천천히.<br><br>적히는 중이다. 누가 적는 게 아니라 저절로.<br>다 적히면 팔린 것이 된다.`,
        dieText:`값이 매겨졌다.<br><br>도박사는 늘 값을 매기는 쪽이었는데.<br>매겨지는 쪽이 되는 건 이번이 처음이다.` },
      good:`찾았다. 없다.<br><br>스물셋 개의 이름이 있고 이쪽 것은 없다.<br>아직 안 들어온 것으로 되어 있다.<br><br>없는 게 이렇게 반가울 줄 몰랐다.`, flag:'notListed' }
  ] }
];

EPIC_SCENES.village.job.gambler = [
{ title:'빈 마을 — 내기',
  text:`집이 스물셋이고 연기가 스물넷이다.<br><br>
    세어 보니 그렇다. 몇 번 세어도 그렇다.<br>
    도박사는 이런 걸 그냥 못 넘긴다.<br><br>
    어느 굴뚝이 가짜인지 맞히면 뭔가 있을 것 같다.`,
  opts:[
    { l:'① 하나를 찍는다.', dc:14, kind:'luck', p:800,
      good:`한참 보고 찍었다. 가장 오래 흔들리지 않던 연기.<br><br>그쪽으로 가 보니 굴뚝이 없다. 연기만 있다.<br>맞혔다.<br><br>연기가 흩어지며 바닥에 뭔가 떨어졌다. 동전이다. 오래된 것.`, flag:'guessedRight',
      bad:`찍었다. 틀렸다.<br><br>찍은 집의 문이 열린다. 안에서 밥상이 차려지는 소리가 난다.<br>틀린 쪽으로 오라는 뜻 같았다.`, poll:8 },
    { l:'② 안 찍는다.', dc:9, p:350,
      good:`세는 걸 그만뒀다.<br><br>도박사가 판을 안 벌이는 건 드문 일이다.<br>드문 일을 한 날은 대개 오래 산다.`, flag:'noBet',
      bad:`그만두려는데 자꾸 세게 된다.<br><br>스물넷, 스물다섯.<br>보지 않기로 하고 눈을 감았다.`, poll:5 }
  ] }
];

