EPIC_SCENES.castle.job.assassin = (EPIC_SCENES.castle.job.assassin || []).concat([

{ title:'성 — 숨을 세는 법',
  text:`방 안에 여럿이 있다.<br><br>
    숨소리가 겹친다. 겹치는 사이에 빈 박자가 있다.<br>
    그 박자에 움직이면 숨소리에 묻힌다.<br><br>
    암살자가 제일 먼저 배우고 마지막까지 쓰는 기술이다.`,
  opts:[
    { l:'① 빈 박자에 움직인다.', mini:'beat', miniOpt:{ p:850, total:12, gap:660 },
      good:`열두 번. 한 번도 어긋나지 않았다.<br><br>방을 가로질렀다. 아무도 고개를 들지 않았다.<br>건너편에서 돌아보니 그대로 있다.<br><br>지나간 적 없는 것처럼. 그게 잘한 것이다.`, flag:'breathStep',
      bad:`한 박자 빨랐다.<br><br>숨소리 사이에 발소리가 끼었다.<br>하나가 숨을 멈춘다. 멈춘 사람은 듣고 있는 사람이다.` },
    { l:'② 잠긴 문을 연다.', mini:'lock', miniOpt:{ p:750, rounds:3, hard:1 },
      good:`소리 없이 열었다.<br><br>안쪽은 좁은 통로다. 벽에 손자국이 가득하다.<br>같은 일을 하던 사람들이 지나간 길이다.<br><br>손자국 위에 손을 얹어 봤다. 크기가 비슷했다.`, flag:'hiddenPassage',
      bad:`마지막 핀에서 소리가 났다.<br><br>작다. 아주 작다.<br>작은 소리를 듣는 것들이 여기 산다.` }
  ] },

{ title:'성 — 표적',
  text:`방 안쪽에 하나 앉아 있다.<br><br>
    등을 보이고 있다. 움직이지 않는다.<br>
    암살자에게 이보다 좋은 자세는 없다.<br><br>
    다만 누구를 죽이러 온 게 아니다. 여긴 그런 자리가 아니다.`,
  opts:[
    { l:'① 그냥 지나간다.', dc:12, kind:'hide', p:700,
      good:`지나갔다. 손을 대지 않았다.<br><br>등이 한 번 들썩였다. 알고 있었던 것이다.<br>알면서 가만히 있어 준 것이다.<br><br>고맙다고 할 수는 없었다.`, flag:'passedTarget',
      bad:`지나치는데 그림자가 그 위로 지났다.<br><br>등이 굳는다. 고개가 돌아가기 시작한다.<br>걸음을 빨리했다.`, poll:7 },
    { l:'② 누구인지 확인한다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'얼굴', what:'표적과 눈이 마주쳤습니다', dc:14, sec:70,
        text:`앞으로 돌아가 얼굴을 봤다.<br><br>얼굴이 있다. 아는 얼굴이다.<br>거울에서 본 얼굴.<br><br>눈이 마주친다. 저쪽이 먼저 일어선다.<br>같은 훈련을 받은 몸이 어떻게 움직이는지는 이쪽이 제일 잘 안다.`,
        dieText:`같은 손이 같은 자리를 노린다.<br><br>먼저 닿은 쪽이 이긴다.<br>먼저 움직인 쪽은 이쪽이 아니었다.` },
      good:`앞으로 돌아갔다. 얼굴이 없다.<br><br>없는 얼굴이 이쪽을 향한다. 다만 아무 일도 안 일어났다.<br>없는 얼굴은 알아보지 못한다.<br><br>얼굴이 없는 게 이쪽에게 유리하게 작용한 건 처음이다.`, flag:'facelessOne' }
  ] },

{ title:'성 — 이름을 남기지 않는다',
  text:`벽에 글자가 있다.<br><br>
    여기를 지난 사람들이 남긴 것이다. 이름이다.<br>
    스물셋 개.<br><br>
    남기면 지나간 것이 되고, 지나간 것은 기억된다.<br>
    암살자는 기억되면 안 된다.`,
  opts:[
    { l:'① 남기지 않는다.', dc:11, p:600,
      good:`지나쳤다. 아무것도 안 적었다.<br><br>적고 싶은 마음이 들었다는 게 놀라웠다.<br>여기 오래 있으면 누구나 이름을 남기고 싶어지는 모양이다.`, flag:'noName',
      bad:`안 적으려는데 손이 벽에 닿았다.<br><br>닿은 자리에 자국이 남는다.<br>지우려고 문지르자 더 선명해졌다.`, poll:7 },
    { l:'② 남은 이름을 지운다.', dc:14, kind:'break', p:800,
      doom:{ title:'지운 이름', what:'이름이 옮겨붙었습니다', dc:14, sec:70,
        text:`긁어서 지웠다. 하나씩.<br><br>열 개쯤 지웠을 때 손등에 글자가 생긴다.<br>지운 이름이 옮겨 온 것이다.<br><br>문질러도 안 지워진다. 파고든다.<br>스물셋 개가 전부 옮겨 오면 어떻게 되는지는 짐작이 간다.`,
        dieText:`이름이 스물셋 개 붙었다.<br><br>이름이 없는 것이 암살자의 조건이다.<br>스물셋 개나 가진 건 아무것도 아닌 것과 같다.` },
      good:`세 개만 지웠다. 가장 오래된 것들로.<br><br>오래된 것부터 놓아주는 게 순서다.<br>손등에 흐릿하게 자국이 남았다. 씻으니 지워졌다.`, flag:'erasedThree' },
    { l:'③ 이름을 읽는다.', dc:13, kind:'gaze', p:700,
      good:`읽었다. 모르는 이름들이다.<br><br>다만 직업이 같이 적혀 있다. 스물셋 개의 직업.<br>겹치는 게 하나도 없다.<br><br>이쪽 직업도 목록에 있다. 이름만 다르다.`, flag:'readNames',
      bad:`읽는데 하나가 이쪽 이름이다.<br><br>아직 적은 적 없는데 적혀 있다.<br>지우려다 그만뒀다.`, poll:9 }
  ] },

{ title:'성 — 등을 맡긴다',
  text:`암살자는 등을 안 맡긴다.<br><br>
    맡기면 죽는다고 배웠다.<br>
    다만 이 복도는 혼자 지날 수 없게 생겼다.<br><br>
    양쪽에서 동시에 봐야 하는 구조다.`,
  opts:[
    { l:'① 동료에게 뒤를 맡긴다.', co:'sync',
      coOpt:{ ask:'뒤를 봐 줄 사람이 필요합니다.', sec:60, p:1000,
        text:`혼자서는 양쪽을 못 본다.`,
        doneText:`등을 맞대고 섰다.<br><br>이쪽이 앞을 보고 저쪽이 뒤를 봤다.<br>지나가는 동안 저쪽 등이 계속 닿아 있었다.<br><br>맡기고도 죽지 않은 건 처음이다.<br>배운 게 전부 맞는 건 아니었다.`,
        failText:`아무도 오지 않았다.<br><br>등을 벽에 붙이고 게걸음으로 지났다.<br>벽은 배신하지 않는다. 그게 벽의 장점이다.` },
      good:`맡겼다.`, bad:`혼자 지났다.`, flag:'trustedBack' }
  ] }
]);

EPIC_SCENES.tower.job.assassin = [
{ title:'탑 — 위에서 아래로',
  text:`탑은 암살자에게 좋은 자리다.<br><br>
    위에서는 전부 보이고 아래에서는 안 보인다.<br>
    다만 내려갈 길이 하나뿐이다.<br><br>
    길이 하나면 좋은 자리가 아니다.`,
  opts:[
    { l:'① 밖으로 내려간다.', dc:14, kind:'evade', p:800,
      doom:{ title:'바깥 벽', what:'벽에 매달려 있습니다', dc:13, sec:65,
        text:`창으로 나가 벽을 탔다.<br><br>탑이 기울어 있어 바깥쪽이 오목하다. 붙어 있기 편하다.<br>편해서 방심했다.<br><br>돌 하나가 빠진다. 발이 헛돈다.<br>손가락 두 개로 매달려 있다. 아래가 안 보인다.`,
        dieText:`손가락이 풀렸다.<br><br>암살자는 높은 데서 내려오는 일을 자주 한다.<br>자주 하는 일에서 죽는 게 대개 그렇다.` },
      good:`벽을 타고 내려왔다.<br><br>손끝이 까졌다. 그래도 아무도 못 봤다.<br>계단으로 내려온 사람은 전부 봤을 것이다.`, flag:'climbedDown' },
    { l:'② 계단으로 내려간다.', dc:11, p:500,
      good:`계단으로 내려왔다. 올라갈 때보다 한 칸 적다.<br><br>세어 봤으니 안다. 스물넷이 스물셋이 됐다.<br>한 칸이 어디 갔는지는 모르겠다.`, flag:'countedDown',
      bad:`내려가는데 위에서 발소리가 따라온다.<br><br>같은 박자다.<br>멈췄다. 저쪽도 멈췄다.`, poll:7 }
  ] }
];

EPIC_SCENES.grave.job.assassin = (EPIC_SCENES.grave.job.assassin || []).concat([
{ title:'묘지 — 같은 일을 하던 사람들',
  text:`백지 비석 스물셋.<br><br>
    이름을 안 남긴 사람들의 무덤이다.<br>
    성벽에 적힌 이름은 스물셋이었다. 여기 비석도 스물셋이다.<br><br>
    적힌 쪽과 묻힌 쪽이 같은 수다.`,
  opts:[
    { l:'① 비석 앞에 이름을 놓는다.', dc:13, kind:'bond', p:800,
      good:`성벽에서 읽은 이름을 기억나는 대로 적어 놓았다.<br><br>종이에 적어 비석 앞에 돌로 눌러 뒀다.<br>새기지는 않았다. 새기면 안 될 것 같아서.<br><br>바람이 안 부는데 종이가 한 번 들썩였다.`, flag:'laidNames',
      bad:`적으려는데 이름이 안 떠오른다.<br><br>분명히 읽었는데 하나도 안 남았다.<br>읽은 게 아니라 읽힌 것이었는지도 모르겠다.`, poll:8 }
  ] }
]);

// ==========================================
// 🪤 밀렵꾼
// ==========================================
EPIC_SCENES.forest.job.poacher = (EPIC_SCENES.forest.job.poacher || []).concat([

{ title:'검은 숲 — 덫의 장력',
  text:`덫을 놓으려면 장력을 맞춰야 한다.<br><br>
    세면 부러뜨리고 약하면 놓친다.<br>
    잡으려는 것 무게에 맞춰야 한다.<br><br>
    여기 것들이 얼마나 나가는지는 아직 모른다.`,
  opts:[
    { l:'① 무게를 재어 맞춘다.', mini:'scale', miniOpt:{ p:800, target:21, pool:[2,4,6,7,9,12] },
      good:`맞췄다.<br><br>놓고 물러나 기다렸다. 얼마 안 가 닫히는 소리가 났다.<br>가서 보니 산 채로 걸려 있다. 다치지 않았다.<br><br>밀렵꾼의 솜씨는 죽이지 않고 잡는 데서 갈린다.`, flag:'rightTension',
      bad:`세게 맞췄다.<br><br>닫히는 소리가 컸다. 가 보니 걸린 것이 움직이지 않는다.<br>산 채로 가져가려던 것이었는데.` },
    { l:'② 숨소리로 무게를 짐작한다.', mini:'beat', miniOpt:{ p:750, total:10, gap:900 },
      good:`숨 간격을 세었다. 느리다. 큰 것이다.<br><br>덫을 크게 놓고 물러났다.<br>짐작이 맞았다. 큰 게 걸렸다. 덫이 버텼다.`, flag:'guessedSize',
      bad:`간격을 놓쳤다.<br><br>숨이 둘이었다. 하나인 줄 알았다.<br>덫 하나로는 안 되는 상황이었다.` }
  ] },

{ title:'검은 숲 — 금렵구의 주인',
  text:`말뚝 안쪽에 뭔가 서 있다.<br><br>
    말뚝을 박은 쪽인지 갇힌 쪽인지 모르겠다.<br>
    이쪽을 본다. 화내지 않는다.<br><br>
    밀렵꾼을 여럿 봤다는 눈이다.`,
  opts:[
    { l:'① 잡은 것을 내려놓는다.', dc:12, kind:'bond', p:750,
      good:`자루를 내려놓고 물러났다.<br><br>그것이 자루를 본다. 그리고 이쪽을 본다.<br>손을 젓는다. 가져가라는 뜻이었다.<br><br>도로 집어 들었다. 허락받고 가져가는 밀렵은 밀렵이 아니지만,<br>그래도 나가는 게 우선이다.`, flag:'permitted',
      bad:`내려놓으려는데 자루가 움직인다.<br><br>안에서 나가려고 발버둥친다. 주인 쪽으로.<br>붙잡고 있는 손이 부끄러웠다.`, poll:8 },
    { l:'② 등을 보이고 달아난다.', dc:14, kind:'evade', p:800,
      doom:{ title:'말뚝 안', what:'금렵구에 갇혔습니다', dc:14, sec:70,
        text:`돌아서 뛰었다.<br><br>말뚝이 보인다. 넘으면 된다.<br>넘으려는데 말뚝이 높아져 있다.<br><br>높아진 게 아니라 촘촘해졌다. 사이가 좁다.<br>돌아보니 그것이 천천히 온다. 서두르지 않는다.<br>서두를 이유가 없다.`,
        dieText:`말뚝은 나가지 말라고 박은 것이었다.<br><br>들어오는 건 아무나 하고, 나가는 건 허락이 필요했다.<br>허락을 안 받고 나가려 했다.` },
      good:`뛰었다. 말뚝을 넘었다.<br><br>넘고 나서 돌아봤다. 그것이 말뚝 안쪽에 서 있다.<br>못 넘는 것이다.<br><br>말뚝은 저것을 가두는 것이었다.`, flag:'escapedPen' }
  ] },

{ title:'검은 숲 — 자루 속',
  text:`자루가 무거워진다.<br><br>
    처음엔 가벼웠다. 걷는 동안 계속 무거워진다.<br>
    안에서 자라는 것 같다.<br><br>
    열어 보면 확인할 수 있다. 열면 놓칠 수도 있다.`,
  opts:[
    { l:'① 열어 본다.', dc:13, kind:'sense', p:700,
      doom:{ title:'자루', what:'자루에서 나온 것이 붙었습니다', dc:13, sec:65,
        text:`열었다.<br><br>안에 든 것이 아까보다 크다. 자루를 꽉 채웠다.<br>깃이 아니라 털이다. 언제 바뀌었는지 모르겠다.<br><br>손을 넣자 잡는다. 놓지 않는다.<br>팔을 타고 올라온다. 어깨까지.`,
        dieText:`밀렵꾼은 산 것을 가져가는 사람이다.<br><br>산 것은 가져가는 도중에도 살아 있다.<br>그걸 잊었다.` },
      good:`열었다. 그대로다. 작고 조용하다.<br><br>무거워진 건 자루가 아니라 팔이었다.<br>오래 들고 있었다.<br><br>고쳐 메고 계속 걸었다.`, flag:'checkedSack' },
    { l:'② 그대로 간다.', dc:11, p:550,
      good:`안 열고 걸었다.<br><br>말뚝 밖에 나오자 다시 가벼워졌다.<br>안쪽에서만 무거운 것이었다.`, flag:'keptClosed',
      bad:`계속 걸었다. 계속 무거워진다.<br><br>말뚝 밖에 나와서도 무겁다.<br>내려놓고 보니 자루 바닥이 젖어 있었다.`, poll:9 }
  ] },

{ title:'검은 숲 — 나눠 지고 간다',
  text:`자루가 혼자 들기에는 무겁다.<br><br>
    두 사람이면 간다. 혼자면 두 번 왕복해야 하고,<br>
    두 번 왕복하는 동안 한쪽은 놓고 가야 한다.<br><br>
    놓고 간 것은 대개 없어진다.`,
  opts:[
    { l:'① 동료와 나눠 진다.', co:'handoff',
      coOpt:{ ask:'무거운 것이 있습니다. 같이 질 사람이 필요합니다.', sec:60, p:950,
        text:`둘이면 한 번에 간다.`,
        doneText:`둘이서 양쪽을 들었다.<br><br>무거운 게 아니었다. 혼자 드는 게 무거웠던 것이다.<br>말뚝 밖까지 한 번에 나왔다.<br><br>내려놓고 둘 다 손을 털었다. 자루 안이 조용했다.`,
        failText:`혼자 두 번 왕복했다.<br><br>두 번째로 돌아왔을 때 놓고 간 자루가 없었다.<br>있던 자리에 털만 남아 있었다.` },
      good:`같이 졌다.`, bad:`하나 잃었다.`, flag:'carriedTogether' }
  ] }
]);

EPIC_SCENES.lake.job.poacher = [
{ title:'거울 호수 — 물가의 것',
  text:`물가에 발자국이 있다.<br><br>
    물에서 나와 물로 들어간 자국이다.<br>
    나온 자국과 들어간 자국 사이에 뭔가 놓여 있다.<br><br>
    알이다. 여러 개.`,
  opts:[
    { l:'① 하나만 가져간다.', dc:12, kind:'hide', p:700,
      good:`하나 집었다. 따뜻하다.<br><br>나머지는 그대로 뒀다. 밀렵꾼에게도 규칙이 있다.<br>다 가져가면 다음이 없다.<br><br>품에 넣으니 심장 옆에서 조금씩 움직였다.`, flag:'oneEgg',
      bad:`집는 순간 물이 흔들린다.<br><br>나오는 중이다. 크다.<br>놓고 물러났다.`, poll:8 },
    { l:'② 전부 가져간다.', dc:15, p:900,
      doom:{ title:'둥지', what:'물에서 나온 것이 쫓아옵니다', dc:14, sec:70,
        text:`전부 담았다. 여섯 개.<br><br>물이 갈라진다. 나온다.<br>크다. 물가에 올라오는 데 한참 걸릴 만큼 크다.<br><br>뛰었다. 자루가 무거워 못 뛴다.<br>버리면 될 텐데 손이 안 놓인다.`,
        dieText:`다 가져가면 다음이 없다.<br><br>밀렵꾼이 제일 먼저 배우고 제일 자주 어기는 규칙이다.<br>어기면 대개 이렇게 된다.` },
      good:`전부 담고 뛰었다.<br><br>물이 흔들렸지만 나오지는 않았다.<br>한참 뛰고 나서 돌아봤다. 아무것도 없다.<br><br>운이 좋았다. 이번만.`, flag:'tookAll' }
  ] }
];

EPIC_SCENES.village.job.poacher = [
{ title:'빈 마을 — 가축이 없다',
  text:`마을에 우리가 있다.<br><br>
    비어 있다. 문이 열린 채로.<br>
    밀렵꾼 눈에는 이런 게 먼저 들어온다.<br><br>
    바닥에 짚이 눌려 있다. 최근까지 뭔가 있었다.`,
  opts:[
    { l:'① 눌린 자리를 본다.', dc:12, kind:'sense', p:650,
      good:`자국이 사람 것이다.<br><br>가축 우리에 사람이 있었다.<br>스물셋 개의 자리가 눌려 있다.<br><br>문은 밖에서 열려 있었다.`, flag:'penPrints',
      bad:`짚을 들추자 아래가 젖어 있다.<br><br>오래된 것이 아니다.<br>덮어 두고 나왔다.`, poll:8 }
  ] }
];

