// ⛏ 도굴꾼
// ==========================================
EPIC_SCENES.grave.job.digger = (EPIC_SCENES.grave.job.digger || []).concat([

{ title:'묘지 — 관 자물쇠',
  text:`관에 자물쇠가 걸려 있다.<br><br>
    바깥에서 잠근 것이다. 안에 든 것을 못 나오게.<br>
    부장품을 지키려는 자물쇠는 안쪽에 안 건다.<br><br>
    구조가 오래됐다. 손에 익은 모양.`,
  opts:[
    { l:'① 딴다.', mini:'lock', miniOpt:{ p:850, rounds:3, hard:1 },
      doomOnLose:{ title:'자물쇠', what:'관이 열리고 있습니다', dc:14, sec:70,
        text:`두 번째 핀에서 어긋났다.<br><br>자물쇠가 저절로 돌아간다. 이쪽이 아니라 안에서.<br>뚜껑이 밀린다.<br><br>누르려는데 힘이 세다. 사람 힘이 아니다.<br>바깥에서 잠근 이유를 이제 알겠다.` },
      good:`열었다.<br><br>뚜껑을 반만 열고 안을 봤다. 비어 있다.<br>대신 부장품이 가지런하다. 누가 정리해 뒀다.<br><br>하나만 집었다. 반지다. 작다. 아이 것.`, flag:'openedCoffin' },
    { l:'② 부장품 배열을 읽는다.', mini:'star', miniOpt:{ p:800, n:6, sec:16 },
      good:`놓인 순서대로 짚었다.<br><br>순서가 맞자 가운데 것이 들린다. 저절로.<br>배열이 곧 자물쇠였다.<br><br>들린 것을 집었다. 가볍다.`, flag:'readLayout',
      bad:`순서가 틀렸다.<br><br>짚은 것들이 제자리에서 조금씩 돌아간다.<br>새 배열이 된다. 이번엔 이쪽이 못 읽는 배열이다.` }
  ] },

{ title:'묘지 — 굴을 판다',
  text:`봉분 옆으로 굴을 판다.<br><br>
    위에서 파면 티가 나고 옆에서 파면 안 난다.<br>
    도굴꾼이 쓰는 방식이다.<br><br>
    다만 옆에서 파면 무너진다.`,
  opts:[
    { l:'① 받쳐 가며 판다.', dc:13, p:700,
      good:`나무를 대고 한 뼘씩 팠다.<br><br>느리다. 느린 대신 안 무너졌다.<br>끝에 닿았을 때 손이 떨렸다. 힘이 아니라 긴장 때문이다.`, flag:'bracedDig',
      bad:`받침이 모자란다.<br><br>반쯤 판 데서 그만뒀다. 메우지도 못했다.<br>구멍이 그대로 남았다.`, poll:7 },
    { l:'② 빨리 판다.', dc:15, kind:'break', p:850,
      doom:{ title:'무너진 굴', what:'굴에 묻혔습니다', dc:14, sec:70,
        text:`빨리 팠다. 팔이 들어가고 어깨가 들어가고 몸이 들어갔다.<br><br>안쪽에 닿았을 때 등 뒤가 내려앉았다.<br>흙이 다리를 덮는다. 허리까지.<br><br>기어 나가려는데 앞쪽이 관이다.<br>뒤는 흙이고 앞은 관이다.`,
        dieText:`도굴꾼은 남의 자리를 파는 사람이다.<br><br>파다 보면 자기 자리를 파게 되는 날이 온다.<br>대개 마지막 날이다.` },
      good:`빨리 팠다. 운이 좋았다.<br><br>안쪽에 닿았다. 무너지기 전에 손을 넣어 하나 꺼냈다.<br>꺼내자마자 굴이 주저앉았다.<br><br>손에 쥔 것을 봤다. 값나가는 것은 아니었다.`, flag:'fastDig' }
  ] },

{ title:'묘지 — 붙는 것',
  text:`꺼낸 것이 손에서 안 떨어진다.<br><br>
    쥔 게 아니라 붙었다.<br>
    부장품은 가끔 그런다. 주인이 안 놓아줄 때.<br><br>
    떼어 내는 방법이 몇 가지 있다.`,
  opts:[
    { l:'① 제자리에 도로 넣는다.', dc:11, p:600,
      good:`관에 도로 넣었다. 손이 놓인다.<br><br>빈손으로 나왔다. 도굴꾼에게 빈손은 실패지만,<br>손이 붙은 채로 나가는 것보다는 낫다.`, flag:'putBack',
      bad:`넣으려는데 관이 안 열린다.<br><br>가져가라는 뜻이다.<br>가져가야 하는 것이 있다.`, poll:8 },
    { l:'② 다른 것을 대신 놓는다.', dc:13, kind:'bond', p:800,
      good:`주머니에서 하나 꺼내 놓았다. 가진 것 중 제일 아끼던 것으로.<br><br>손이 놓인다.<br>거래가 된 것이다. 주인이 값을 매긴 셈이다.`, flag:'traded',
      bad:`아무거나 놓았다. 안 놓인다.<br><br>값이 안 맞는 것이었다.<br>더 내놓아야 한다.`, poll:9 },
    { l:'③ 억지로 떼어 낸다.', dc:15, kind:'break', p:900,
      doom:{ title:'붙은 손', what:'손을 떼지 못하고 있습니다', dc:14, sec:70,
        text:`칼로 사이를 긁었다.<br><br>안 떨어진다. 살이 긁힐 뿐이다.<br>붙은 게 아니라 자라고 있다. 손 안쪽으로.<br><br>팔이 무거워진다. 부장품 무게가 아니다.<br>팔 자체가 다른 것이 되어 간다.`,
        dieText:`부장품은 주인과 같이 묻는 것이다.<br><br>주인이 바뀌면 같이 묻힐 사람도 바뀐다.<br>그래서 자리가 하나 필요해진다.` },
      good:`떼어 냈다. 살이 조금 찢어졌다.<br><br>손에 자국이 남았다. 쥐고 있던 모양으로.<br>자국은 며칠이면 없어질 것이다. 아마도.`, flag:'toreFree' }
  ] },

{ title:'묘지 — 망을 본다',
  text:`도굴은 둘이 한다.<br><br>
    하나가 파고 하나가 본다.<br>
    혼자 하면 파는 동안 뒤를 못 본다.<br><br>
    여기서 뒤를 못 보는 건 위험한 정도가 아니다.`,
  opts:[
    { l:'① 동료에게 망을 부탁한다.', co:'standin',
      coOpt:{ ask:'파는 동안 봐 줄 사람이 필요합니다.', sec:60, p:1000,
        text:`혼자서는 파면서 볼 수가 없다.`,
        doneText:`동료가 등 뒤에 섰다.<br><br>파는 동안 세 번 소리를 냈다. 세 번 다 멈췄다.<br>멈춘 덕에 세 번 안 들켰다.<br><br>다 파고 나서 몫을 나눴다. 반씩.<br>망 보는 쪽도 반이다. 그게 규칙이다.`,
        failText:`혼자 팠다.<br><br>파는 내내 뒤가 신경 쓰였다.<br>얕게 파고 그만뒀다.` },
      good:`둘이 했다.`, bad:`혼자 했다.`, flag:'lookout' }
  ] }
]);

EPIC_SCENES.ruin.job.digger = [
{ title:'폐허 — 바닥 아래',
  text:`회랑 바닥에 석판이 깔려 있다.<br><br>
    하나가 헐겁다. 들면 아래가 나온다.<br>
    무덤은 아니다. 다만 무언가 넣어 둔 자리다.<br><br>
    도굴꾼은 무덤만 파는 게 아니다.`,
  opts:[
    { l:'① 석판을 들어낸다.', dc:13, kind:'break', p:700,
      good:`들어냈다. 아래에 공간이 있다.<br><br>상자가 놓여 있다. 부패하지 않은 나무 상자.<br>열어 보니 기록이다. 이름과 날짜.<br><br>스물넷 줄이고 한 줄이 비어 있다.`, flag:'floorBox',
      bad:`들다가 손이 미끄러졌다.<br><br>석판이 떨어져 발등을 쳤다.<br>아래는 못 봤다.`, poll:8 },
    { l:'② 두드려 빈 곳을 찾는다.', mini:'beat', miniOpt:{ p:750, total:10, gap:720 },
      good:`한 칸씩 두드렸다. 열 번.<br><br>세 번째와 여덟 번째가 비었다.<br>둘 다 열어 봤다. 하나는 비었고 하나는 아래로 이어진다.<br><br>이어지는 쪽으로 내려갔다.`, flag:'hollowFloor',
      bad:`두드리는 박자가 흐트러졌다.<br><br>아래에서 같은 박자로 두드린다.<br>맞춰 주는 것이다.` }
  ] }
];

EPIC_SCENES.temple.job.digger = [
{ title:'신전 — 제단 아래',
  text:`제단이 깨져 있다.<br><br>
    깨진 틈으로 아래가 보인다. 비어 있다.<br>
    신전 제단 아래에는 대개 뭔가 묻는다.<br><br>
    묻었던 것이 없다는 건 누가 먼저 왔다는 뜻이다.`,
  opts:[
    { l:'① 먼저 온 자국을 찾는다.', dc:13, kind:'sense', p:700,
      good:`흙에 자국이 있다. 손자국이다.<br><br>손가락이 여섯이다. 세 번 세었다.<br>먼저 온 것은 사람이 아니었다.<br><br>가져간 것이 뭔지는 모르겠다. 다만 사람이 쓸 것은 아니었을 것이다.`, flag:'sixFingers',
      bad:`자국을 만지자 흙이 무너진다.<br><br>아래로 더 깊은 공간이 드러난다.<br>깊다. 아주 깊다.`, poll:9 }
  ] }
];
;

