epicSlot('village', 'spy').push(
{ title:'빈 마을 — 집집의 표식',
  text:`문마다 표식이 있다.<br><br>
    분필 자국인데 두 종류가 겹쳐 있다.<br>
    성벽에서 본 것과 같은 방식이다.<br><br>
    두 진영이 이 마을을 각자 표시했다는 뜻이다.`,
  opts:[
    { l:'① 어느 쪽이 먼저인지 본다.', dc:13, kind:'gaze', p:700,
      good:`겹친 순서를 봤다. 한쪽이 확실히 아래다.<br><br>아래쪽 표식이 "비었음"이고 위쪽이 "있음"이다.<br>비운 뒤에 채웠다는 뜻이다.<br><br>무엇으로 채웠는지는 집 안에 있다.`, flag:'twoMarks',
      bad:`겹친 게 너무 많다.<br><br>스물셋 번쯤 덧그어졌다.<br>순서를 읽을 수가 없다.`, poll:7 },
    { l:'② 이쪽 표식을 덧그린다.', dc:12, p:650,
      good:`세 번째 표식을 남겼다. 이쪽 방식으로.<br><br>다음에 오는 밀정이 읽을 것이다.<br><span style="color:#d4af37;">"둘 다 왔다 갔음. 들어가지 말 것."</span>`, flag:'thirdMark',
      bad:`덧그리는데 아래 두 개가 지워진다.<br><br>세 개가 같이 있을 수 없는 자리였다.<br>하나만 남았다. 이쪽 것이다.`, poll:8 }
  ] }
);

epicSlot('temple', 'spy').push(
{ title:'신전 — 양쪽이 기도한 자리',
  text:`손자국이 겹쳐 있다.<br><br>
    크기가 다 다르다. 두 무리가 같은 자리에서 빌었다는 뜻이다.<br>
    서로 싸우던 쪽이 같은 곳에서 같은 것을 빌었다.<br><br>
    밀정은 이런 걸 보면 보고할지 말지 고민한다.`,
  opts:[
    { l:'① 기록해 둔다.', dc:12, p:650,
      good:`손자국 배치를 그려 뒀다.<br><br>양쪽이 같은 걸 빌었다는 증거다.<br>이런 건 어느 쪽에 보고해도 반가워하지 않는다.<br><br>그래서 밀정이 가지고 있게 된다.`, flag:'bothPrayed',
      bad:`그리는데 자국이 옅어진다.<br><br>그린 만큼 벽에서 사라진다.<br>옮겨 온 것이다. 종이를 접어 넣었다.`, poll:7 },
    { l:'② 손을 대 본다.', dc:14, kind:'gaze', p:750,
      doom:{ title:'겹친 손', what:'손이 벽에 붙었습니다', dc:14, sec:70,
        text:`제일 큰 자국에 손을 맞췄다.<br><br>맞는다. 이쪽 손과 같은 크기다.<br>붙는다. 벽이 손을 받아들인다.<br><br>빌던 사람들 손이 왜 자국으로 남았는지 알겠다.<br>손이 아니라 사람이 남은 것이다.`,
        dieText:`밀정은 양쪽을 다 아는 사람이다.<br><br>양쪽 다 아는 사람은 양쪽 다 놓지 않는다.<br>벽에 자국이 하나 늘었다.` },
      good:`손을 댔다가 곧 뗐다.<br><br>미지근하다. 오래 대고 있으면 안 될 온도다.<br>떼고 나서 손바닥을 봤다. 자국이 옮아 있다.<br><br>씻으니 지워졌다. 다행이다.`, flag:'touchedPrints' }
  ] }
);

epicSlot('ruin', 'spy').push(
{ title:'폐허 — 숨어 듣던 자리',
  text:`기둥 뒤에 웅크린 자국이 있다.<br><br>
    오래 앉아 있던 자국이다. 밀정이 쓰던 자리다.<br>
    여기서 회랑이 다 들린다.<br><br>
    앞서 온 동업자가 있었다는 뜻이다.`,
  opts:[
    { l:'① 앉아서 들어 본다.', dc:12, kind:'sense', p:650,
      good:`앉으니 소리가 모인다. 회랑 구조가 그렇게 되어 있다.<br><br>멀리서 발소리가 들린다. 여럿이다.<br>세어 보니 넷. 넷이 같은 박자로 걷는다.<br><br>훈련받은 걸음이다.`, flag:'listenPost',
      bad:`앉았더니 이쪽 숨소리가 모인다.<br><br>모여서 회랑으로 퍼진다.<br>듣던 자리가 들리는 자리이기도 했다.`, poll:7 },
    { l:'② 앞사람 흔적을 찾는다.', dc:13, kind:'gaze', p:700,
      good:`기둥 아래에 긁은 자국이 있다. 세는 표시다.<br><br>스물셋 개. 스물셋 번 앉았다는 뜻이거나,<br>스물셋을 셌다는 뜻이다.<br><br>스물넷째 자리가 비어 있다. 긁다 만 자국이 있다.`, flag:'tallyMarks',
      bad:`찾다 보니 이쪽이 방금 긁은 자국이 있다.<br><br>긁은 적이 없다. 손톱을 봤다. 흙이 끼어 있다.`, poll:9 }
  ] }
);

epicSlot('lake', 'spy').push(
{ title:'거울 호수 — 비친 표식',
  text:`물가 바위에 표식이 있다.<br><br>
    물에 비쳐야 읽히는 방식이다. 거꾸로 새겨 놓았다.<br>
    밀정이 쓰는 방식 중 제일 번거로운 것.<br><br>
    번거로운 방식은 중요한 걸 숨길 때 쓴다.`,
  opts:[
    { l:'① 물에 비춰 읽는다.', dc:13, kind:'gaze', p:750,
      good:`몸을 숙여 수면에 비친 것을 읽었다.<br><br><span style="color:#d4af37;">"스물셋은 안에 있다. 스물넷째를 찾지 마라."</span><br><br>찾지 말라는 건 찾을 수 있다는 뜻이다.<br>밀정은 그런 식으로 읽는다.`, flag:'mirrorMark',
      bad:`비친 것을 읽는데 수면이 흔들린다.<br><br>흔들려서가 아니라 아래에서 뭔가 지나갔다.<br>다 못 읽었다.`, poll:8 },
    { l:'② 답신을 새긴다.', dc:12, p:700,
      good:`옆 바위에 거꾸로 새겼다.<br><span style="color:#d4af37;">"읽었음. 다음 사람에게."</span><br><br>새기는 데 오래 걸렸다. 거꾸로 새기는 건 원래 그렇다.<br>다음 밀정이 읽을 것이다.`, flag:'wroteBack',
      bad:`새기는데 바로 새겨진다.<br><br>손은 거꾸로 움직이는데 글자가 바로 나온다.<br>물이 아니라 바위가 거울이었다.`, poll:7 }
  ] }
);

epicSlot('grave', 'spy').push(
{ title:'묘지 — 동업자들',
  text:`백지 비석 스물셋.<br><br>
    이름 없이 묻힌다는 건 이 일을 하던 사람들 방식이다.<br>
    암살자도 그렇고 밀정도 그렇다.<br><br>
    다만 밀정은 이름이 둘이라 하나도 안 남는다.`,
  opts:[
    { l:'① 가명을 새겨 둔다.', dc:12, kind:'bond', p:750,
      good:`이쪽이 쓰던 가명을 하나 새겼다.<br><br>본명이 아니니 상관없다. 밀정에게 가명은 옷 같은 것이다.<br>벗어 둘 수 있다.<br><br>새기고 나니 가벼워졌다. 이름 하나를 내려놓은 셈이다.`, flag:'aliasCarved',
      bad:`새기는데 손이 본명을 쓴다.<br><br>세 글자 쓰고 멈췄다. 긁어서 지웠다.<br>지운 자국이 남았다.`, poll:9 },
    { l:'② 동료와 서로의 가명을 새긴다.', co:'witness',
      coOpt:{ ask:'서로의 이름을 새겨 줄 사람이 필요합니다.', sec:60, p:950,
        text:`제 이름을 제가 새기면 무덤이 된다. 남이 새기면 기록이 된다.`,
        doneText:`서로의 가명을 새겨 줬다.<br><br>이쪽이 저쪽 것을, 저쪽이 이쪽 것을.<br>둘 다 본명은 안 물었다.<br><br>새긴 것이 두 개 늘었다. 둘 다 무덤이 아니라 기록이 됐다.`,
        failText:`혼자 새겼다. 가명으로.<br><br>새기고 나서 한참 봤다.<br>남이 새겨 줬으면 달랐을 것이다.` },
      good:`기록이 됐다.`, bad:`혼자 새겼다.` }
  ] }
);

epicSlot('road', 'spy').push(
{ title:'끊긴 길 — 양쪽으로 가는 길',
  text:`끊긴 자리 양쪽에 표식이 있다.<br><br>
    한쪽은 이쪽 진영, 한쪽은 저쪽 진영 것.<br>
    건너면 저쪽 쪽으로 간 것이 된다.<br><br>
    밀정에게 건넌다는 건 단순한 이동이 아니다.`,
  opts:[
    { l:'① 건넌다.', dc:13, p:750,
      doom:{ title:'건넌 뒤', what:'양쪽에서 쫓기고 있습니다', dc:15, sec:70,
        text:`건넜다.<br><br>건너자마자 뒤쪽 표식이 지워진다. 돌아갈 자리가 없어졌다.<br>앞쪽 표식도 지워진다. 받아 주지 않는다는 뜻이다.<br><br>양쪽 다 아닌 자리에 섰다.<br>안개에서 뭔가 올라온다. 양쪽에서.`,
        dieText:`밀정은 양쪽에 속해서 어느 쪽도 아닌 사람이다.<br><br>평소에는 그게 안전하다.<br>양쪽이 동시에 찾을 때만 아니면.` },
      good:`건넜다. 표식을 둘 다 지우고 건넜다.<br><br>어느 쪽에서 왔는지 모르게 해 두는 것이 순서다.<br>건너편에서 돌아봤다. 아무 자국도 없다.<br><br>없는 게 제일 안전하다.`, flag:'crossedClean' },
    { l:'② 건너지 않고 표식만 남긴다.', dc:11, p:600,
      good:`양쪽에 같은 표식을 남겼다.<br><br>여기서 끊겼다는 표시다. 다음 사람이 헛걸음하지 않게.<br>밀정이 할 수 있는 친절은 이 정도다.`, flag:'markedBreak',
      bad:`남기는데 한쪽 분필이 없다.<br><br>한쪽에만 남았다. 한쪽에만 남은 표식은 편든 것이 된다.<br>지우려 했는데 안 지워졌다.`, poll:8 }
  ] }
);
;

