epicSlot('market', 'swordsman').push(
{ title:'장터 — 날을 보는 눈',
  text:`좌판에 칼이 놓여 있다.<br><br>
    열두 자루쯤 된다. 값이 안 적혀 있다.<br>
    검사는 값보다 날을 먼저 본다.<br><br>
    전부 날이 서 있다. 한 자루만 무디다.`,
  opts:[
    { l:'① 무딘 것을 고른다.', dc:12, kind:'sense', p:600,
      good:`무딘 것을 집었다.<br><br>무딘 게 아니라 많이 쓴 것이다. 날이 닳도록 쓴 칼.<br>손잡이에 손자국이 배어 있다.<br><br>가져왔다. 잘 드는 칼보다 낫다.`, flag:'wornSword',
      bad:`집는 순간 주인이 고개를 든다.<br><br>얼굴이 없다. 없는 얼굴로 그 칼을 본다.<br>내려놓았다. 그것 하나만은 안 되는 모양이다.`, poll:6 },
    { l:'② 전부 들어 본다.', dc:13, p:650,
      good:`하나씩 들어 무게를 봤다.<br><br>전부 같은 무게다. 다른 대장장이가 만들 수 없는 일이다.<br>한 사람이 만든 것이다. 열두 자루를.<br><br>만든 사람이 어디 있는지 물어볼 데가 없었다.`, flag:'sameWeight',
      bad:`들다가 손이 베였다.<br><br>날이 아니라 손잡이에 베였다.<br>손잡이가 날이었다.`, poll:7 }
  ] }
);

epicSlot('village', 'swordsman').push(
{ title:'빈 마을 — 벽에 걸린 것',
  text:`집집마다 벽에 뭔가 걸려 있다.<br><br>
    농기구다. 낫, 도끼, 쇠스랑.<br>
    전부 날이 서 있다. 농기구 날이 이렇게 설 이유가 없다.<br><br>
    갈아 놓은 것이다. 뭔가를 막으려고.`,
  opts:[
    { l:'① 갈린 방향을 본다.', dc:12, kind:'gaze', p:600,
      good:`안쪽으로 갈려 있다.<br><br>밖을 향해 쓰는 게 아니라 안으로 당겨 쓰게 갈았다.<br>막으려던 게 아니라 붙잡으려던 것이다.<br><br>무엇을 붙잡으려 했는지는 안 적혀 있다.`, flag:'sharpInward',
      bad:`보다가 하나가 떨어진다.<br><br>걸이가 삭은 게 아니라 누가 놓은 것 같다.<br>발등을 비켜 떨어졌다.`, poll:7 },
    { l:'② 하나 챙긴다.', dc:11, p:500,
      good:`낫을 하나 챙겼다. 칼보다 짧지만 쓸 데가 있다.<br><br>검사가 낫을 드는 건 모양이 안 나지만,<br>모양 따질 자리가 아니다.`, flag:'tookScythe',
      bad:`벽에서 안 떨어진다.<br><br>걸린 게 아니라 벽이 쥐고 있다.<br>힘을 줬더니 벽이 같이 딸려 왔다.`, poll:6 }
  ] },

{ title:'빈 마을 — 지켜 주던 자리',
  text:`마을 입구에 흙이 다져져 있다.<br><br>
    누가 오래 서 있던 자리다. 발 자리가 둘.<br>
    앞뒤로 서 있었다. 칼 쓰는 자세다.<br><br>
    여기 서서 마을을 지키던 사람이 있었다.`,
  opts:[
    { l:'① 같은 자세로 서 본다.', dc:12, p:650,
      good:`발을 자국에 맞췄다. 맞는다.<br><br>이 자세로 서면 마을 전체가 보인다. 집 스물셋이 다 보인다.<br>여기서 지켰다는 게 무슨 뜻인지 알겠다.<br><br>오래 서 있었다. 발이 저릴 때 뗐다.`, flag:'guardStance',
      bad:`맞추려는데 자국이 안 맞는다.<br><br>이쪽 발보다 작다. 훨씬 작다.<br>아이 발자국이었다.`, poll:8 },
    { l:'② 동료를 불러 자리를 넘긴다.', co:'standin',
      coOpt:{ ask:'여기 서 있을 사람이 필요합니다. 잠깐이면 됩니다.', sec:55, p:900,
        text:`혼자 서면 못 떠난다.`,
        doneText:`누가 와서 대신 섰다.<br><br>자세는 어색한데 서 있긴 서 있었다.<br>그 사이에 마을을 한 바퀴 돌았다.<br><br>돌아오니 발 자국이 셋이 되어 있다. 이쪽, 앞사람, 그리고 지금 선 사람.`,
        failText:`혼자 서 있었다.<br><br>떠나려는데 발이 안 떨어진다.<br>억지로 뗐다. 자국에서 발을 빼는 느낌이었다.` },
      good:`교대했다.`, bad:`혼자 섰다.` }
  ] }
);

epicSlot('temple', 'swordsman').push(
{ title:'신전 — 칼을 두고 들어가는 곳',
  text:`입구에 칼꽂이가 있다.<br><br>
    신전에 들어갈 때 칼을 두고 들어가라는 뜻이다.<br>
    꽂이가 비어 있다. 아무도 안 두고 들어갔거나, 두고 나오지 못했거나.<br><br>
    검사에게 칼을 두는 건 손을 두고 가는 것과 같다.`,
  opts:[
    { l:'① 두고 들어간다.', dc:13, kind:'bond', p:750,
      good:`꽂이에 세워 두고 들어갔다.<br><br>손이 허전하다. 자꾸 허리를 더듬는다.<br>안쪽에서 아무 일도 안 일어났다. 두고 들어왔으니까.<br><br>나올 때 그대로 있었다. 두고 들어가도 되는 곳이었다.`, flag:'leftBlade',
      bad:`두고 들어가려는데 칼이 안 놓인다.<br><br>손이 안 펴진다.<br>결국 들고 들어갔다. 들고 들어간 것이 잘못은 아니었다.`, poll:7 },
    { l:'② 들고 들어간다.', dc:14, p:700,
      doom:{ title:'들고 들어간 것', what:'칼이 제단을 향하고 있습니다', dc:14, sec:70,
        text:`들고 들어갔다.<br><br>제단 앞에 서자 칼이 무거워진다.<br>손이 내려간다. 겨누는 자세로.<br><br>겨눌 생각이 없는데 겨눠진다.<br>팔이 이쪽 말을 안 듣는다. 칼이 이쪽을 쓰고 있다.`,
        dieText:`신전에 칼을 들고 들어가지 말라는 건 예의가 아니라 규칙이었다.<br><br>규칙에는 대개 이유가 있다.<br>이유를 확인하고 나면 늦다.` },
      good:`들고 들어갔다. 칼을 등 뒤로 돌려 잡고.<br><br>제단 앞에서 한 번 무릎을 굽혔다.<br>예의는 갖췄다는 뜻으로.<br><br>아무 일도 안 일어났다. 예의로 넘어가는 곳도 있다.`, flag:'carriedIn' }
  ] }
);

epicSlot('lake', 'swordsman').push(
{ title:'거울 호수 — 비친 자세',
  text:`물에 비친 것이 이쪽 자세를 따라 한다.<br><br>
    칼을 들면 저쪽도 든다. 반 박자 늦게.<br>
    검사는 반 박자가 무슨 뜻인지 안다.<br><br>
    반 박자 늦으면 진다.`,
  opts:[
    { l:'① 겨루는 자세로 선다.', dc:14, p:800,
      good:`정면으로 섰다. 저쪽도 섰다.<br><br>먼저 치지 않았다. 저쪽도 안 쳤다.<br>오래 섰다가 칼을 내렸다. 저쪽이 반 박자 늦게 내렸다.<br><br>반 박자 늦는 쪽은 따라 하는 쪽이다. 확인했다.`, flag:'mirrorDuel',
      bad:`섰는데 저쪽이 먼저 친다.<br><br>반 박자 빨랐다.<br>물이 튀었다. 칼에 물이 묻었다. 안 마른다.`, poll:9 },
    { l:'② 물에서 멀어진다.', dc:10, p:450,
      good:`뒤로 물러났다. 비친 것이 안 보이게.<br><br>안 보이면 안 따라 한다.<br>검사가 겨룸을 피하는 건 어려운 일이다. 피했다.`, flag:'steppedBack',
      bad:`물러났는데 물이 따라온다.<br><br>물가가 넓어진다. 발밑이 젖는다.<br>더 물러났다.`, poll:7 }
  ] }
);

epicSlot('grave', 'swordsman').push(
{ title:'묘지 — 묻힌 칼',
  text:`봉분 하나에 칼이 꽂혀 있다.<br><br>
    비석 대신이다. 날이 위로, 자루가 하늘을 본다.<br>
    검사를 묻을 때 그렇게 한다고 들었다.<br><br>
    자루에 손자국이 배어 있다.`,
  opts:[
    { l:'① 뽑는다.', dc:14, kind:'break', p:800,
      doom:{ title:'뽑은 칼', what:'칼이 손을 놓지 않습니다', dc:14, sec:70,
        text:`뽑았다. 잘 뽑힌다.<br><br>손에 익는다. 너무 익는다. 배운 적 없는 자세가 나온다.<br>이 칼을 쓰던 사람 자세다.<br><br>놓으려는데 안 놓인다.<br>손이 자루에 맞춰 굳어 간다. 자국이 하나 더 생기는 중이다.`,
        dieText:`묻힌 칼은 묻힌 이유가 있다.<br><br>쓰던 사람이 못 놓아서 같이 묻은 것이다.<br>이번에도 같이 묻게 됐다.` },
      good:`반쯤 뽑다가 도로 꽂았다.<br><br>손에 익는 느낌이 왔을 때 멈췄다.<br>익는 건 좋은 게 아니다. 여기서는.<br><br>꽂아 두고 한 번 고개를 숙였다.`, flag:'leftBladeGrave' },
    { l:'② 옆에 이쪽 칼을 꽂는다.', dc:12, kind:'bond', p:700,
      good:`옆에 꽂았다. 같은 높이로.<br><br>두 자루가 나란히 섰다.<br>혼자 묻힌 것보다 낫다고 생각했다.<br><br>나올 때 도로 뽑아 왔다. 잠깐 세워 둔 것으로 충분했다.`, flag:'pairedBlades',
      bad:`꽂는데 흙이 밀어낸다.<br><br>세 번 꽂고 세 번 밀려났다.<br>자리가 하나뿐인 봉분이었다.`, poll:7 }
  ] }
);

// ==========================================
// 🔨 대장장이 — 10장면
// ==========================================
epicSlot('gate', 'smith').push(
{ title:'성문 — 경첩',
  text:`아치에 경첩이 남아 있다.<br><br>
    문은 없는데 경첩만 있다. 크다. 사람 팔뚝만 하다.<br>
    이만한 경첩을 만들려면 화덕이 커야 한다.<br><br>
    이 근처에 그만한 대장간이 있었다는 뜻이다.`,
  opts:[
    { l:'① 만든 방식을 본다.', dc:12, kind:'sense', p:600,
      good:`접합부를 봤다. 두드려 붙인 게 아니라 통째로 뽑았다.<br><br>이렇게 만들려면 사람 여럿이 붙어야 한다.<br>혼자서는 못 한다.<br><br>여럿이 있었다는 뜻이다. 한때는.`, flag:'bigHinge',
      bad:`만지자 녹이 떨어진다.<br><br>녹 아래가 붉다. 녹이 아니었다.<br>손에 묻었다. 안 지워진다.`, poll:7 },
    { l:'② 떼어 낸다.', dc:14, kind:'break', p:700,
      good:`정을 대고 쳤다. 여섯 번 만에 떨어졌다.<br><br>무겁다. 지고 갈 수는 없다.<br>쓸 만한 부분만 잘라 챙겼다.`, flag:'hingeIron',
      bad:`치는데 아치가 흔들린다.<br><br>경첩이 아치를 잡고 있었다.<br>그만뒀다.`, poll:8 }
  ] }
);

epicSlot('temple', 'smith').push(
{ title:'신전 — 깨진 제단',
  text:`제단이 깨져 있다.<br><br>
    돌인데 깨진 자리가 금속처럼 갈라졌다. 결이 있다.<br>
    돌이 아니라 주물이다. 부어서 만든 것이다.<br><br>
    신전 제단을 주물로 만들지는 않는다.`,
  opts:[
    { l:'① 결을 읽는다.', dc:13, kind:'gaze', p:700,
      good:`결이 한 방향이다. 한 번에 부었다는 뜻이다.<br><br>이만한 것을 한 번에 부으려면 화덕이 아주 커야 한다.<br>성보다 큰 화덕이 있었다는 얘기가 된다.<br><br>말이 안 되는데 결은 그렇게 말하고 있다.`, flag:'castAltar',
      bad:`결을 따라가다 눈이 어지럽다.<br><br>결이 한 방향이 아니라 소용돌이다.<br>가운데로 빨려드는 모양이다.`, poll:8 },
    { l:'② 조각을 이어 붙인다.', mini:'scale', miniOpt:{ p:800, target:25, pool:[3,5,7,8,10,12] },
      good:`조각을 무게순으로 맞춰 놓았다.<br><br>맞물린다. 딱 맞물린다.<br>깨진 게 아니라 분해된 것이었다.<br><br>맞추니 가운데에 구멍이 있다. 뭔가 들어갈 자리다.`, flag:'altarFit',
      bad:`무게가 안 맞는다.<br><br>조각이 하나 모자란다.<br>가장 큰 조각이 없다.` }
  ] }
);

epicSlot('forest', 'smith').push(
{ title:'검은 숲 — 숯',
  text:`숯가마 자리가 있다.<br><br>
    무너졌지만 형태는 남았다. 여기서 숯을 구웠다.<br>
    대장간이 가까웠다는 뜻이다.<br><br>
    가마 안에 숯이 아직 남아 있다.`,
  opts:[
    { l:'① 숯을 챙긴다.', dc:11, p:550,
      good:`꺼냈다. 가볍고 검다. 좋은 숯이다.<br><br>여기 나무로 구운 것일 텐데 냄새가 나쁘지 않다.<br>자루에 담았다.`, flag:'charcoal',
      bad:`꺼내는데 안쪽이 따뜻하다.<br><br>아직 타고 있다. 몇 해 전에 닫힌 가마가.<br>손을 데었다.`, poll:7 },
    { l:'② 가마를 살핀다.', dc:13, kind:'sense', p:650,
      doom:{ title:'가마 안', what:'가마 속에 갇혔습니다', dc:13, sec:65,
        text:`안을 보려고 몸을 넣었다.<br><br>넓다. 서서 들어갈 만큼.<br>안쪽 벽에 긁은 자국이 있다. 손톱 자국이다.<br><br>입구가 좁아진다. 흙이 아니라 벽이 움직인다.<br>가마는 안에서 열 수 없게 만든다.`,
        dieText:`숯은 나무를 가둬서 만든다.<br><br>공기를 막고 오래 태우면 숯이 된다.<br>나무만 그런 게 아니었다.` },
      good:`허리를 굽혀 안쪽만 들여다봤다.<br><br>벽에 긁은 자국이 있다. 손톱 자국이다.<br>몸을 넣지 않았다. 넣었으면 어떻게 됐을지는 자국이 말해 준다.<br><br>물러났다.`, flag:'kilnMarks' }
  ] }
);

epicSlot('castle', 'smith').push(
{ title:'성 — 무기고',
  text:`무기고가 있다.<br><br>
    걸이가 스물넷이고 걸린 것은 스물셋이다.<br>
    하나가 비어 있다.<br><br>
    대장장이는 만든 것을 알아본다. 전부 같은 손이 만들었다.`,
  opts:[
    { l:'① 만든 사람의 표식을 찾는다.', dc:13, kind:'gaze', p:750,
      good:`자루 끝에 찍힌 표식이 있다. 스물셋 개가 같다.<br><br>표식이 익숙하다. 이쪽이 쓰는 것과 같은 모양.<br>대장장이 표식은 스승에게 물려받는다.<br><br>같은 스승 밑에서 나온 사람이 여기 있었다.`, flag:'smithMark',
      bad:`표식이 지워져 있다.<br><br>스물셋 개 전부. 갈아서 지웠다.<br>만든 사람이 지웠다는 뜻이다. 부끄러워서거나, 숨기려고.`, poll:7 },
    { l:'② 빈 걸이에 맞는 것을 만든다.', co:'sync',
      coOpt:{ ask:'쇠를 잡아 줄 손이 필요합니다. 무기고입니다.', sec:65, p:1000,
        text:`빈 자리를 채우려면 하나 만들어야 한다.`,
        doneText:`동료가 집게를 잡았다.<br><br>가진 쇠를 녹여 하나 만들었다. 투박하다.<br>걸이에 걸었다. 스물넷이 됐다.<br><br>걸자 무기고가 한 번 울렸다. 맞아 들어간 소리다.<br>비어 있던 자리는 채우라고 있는 자리였다.`,
        failText:`혼자 해 봤다. 집게를 무릎으로 눌렀다.<br><br>모양이 안 나온다. 걸이에 안 걸린다.<br>빈 자리는 빈 채로 뒀다.` },
      good:`채웠다.`, bad:`못 채웠다.`, flag:'filledRack' }
  ] }
);

epicSlot('grave', 'smith').push(
{ title:'묘지 — 녹슨 것들',
  text:`비석 사이에 쇠가 박혀 있다.<br><br>
    부러진 연장들이다. 삽, 낫, 정.<br>
    여기서 일하다 부러진 것들을 그 자리에 꽂아 둔 것 같다.<br><br>
    대장장이 눈에는 연장 무덤으로 보인다.`,
  opts:[
    { l:'① 고칠 만한 것을 고른다.', dc:12, p:650,
      good:`셋을 골랐다. 자루만 갈면 쓸 만하다.<br><br>고쳐서 관리소 앞에 놓아뒀다.<br>쓰던 사람이 없어도 연장은 고쳐 두는 게 맞다.<br><br>연장은 고치면 기다린다.`, flag:'fixedTools',
      bad:`고르는데 전부 부스러진다.<br><br>녹이 아니라 속부터 삭았다.<br>쓸 수 있는 게 하나도 없다.`, poll:6 },
    { l:'② 전부 녹여 하나로 만든다.', dc:15, kind:'break', p:850,
      doom:{ title:'녹인 것', what:'쇳물이 손에 붙었습니다', dc:14, sec:70,
        text:`모아서 녹였다. 스물셋 개 분량.<br><br>쇳물이 곱게 나온다. 너무 곱다.<br>부으려는데 틀을 찾기 전에 손으로 흘러온다.<br><br>뜨겁지 않다. 그게 더 나쁘다.<br>손에 감긴다. 팔로 올라온다.`,
        dieText:`연장은 쓰던 사람 손을 기억한다.<br><br>스물셋 개를 한꺼번에 녹이면 스물셋 개의 기억이 나온다.<br>기억은 손을 찾는다.` },
      good:`셋만 녹였다. 부스러진 것들로.<br><br>작은 덩이 하나가 나왔다. 주머니에 넣었다.<br>나머지는 그대로 뒀다. 전부 녹이는 건 아니다 싶었다.`, flag:'meltedThree' }
  ] }
);

// ==========================================
// 🛡 파수꾼 — 10장면
// ==========================================
epicSlot('castle', 'warden').push(
{ title:'성 — 잠긴 방향',
  text:`성문이 안에서 잠겨 있다.<br><br>
    파수꾼은 문을 보면 어느 쪽에서 잠갔는지부터 본다.<br>
    빗장이 안쪽에 있다.<br><br>
    안에 아무도 없는데 안에서 잠갔다.`,
  opts:[
    { l:'① 빗장을 살핀다.', dc:12, kind:'gaze', p:650,
      good:`빗장에 손자국이 없다.<br><br>사람이 걸었으면 자국이 남는다. 없다는 건 사람이 안 걸었다는 뜻이다.<br>문이 스스로 잠근 것이다.<br><br>스스로 잠그는 문은 스스로 열기도 한다. 때가 되면.`, flag:'selfBarred',
      bad:`살피려고 손을 댔더니 빗장이 움직인다.<br><br>이쪽이 민 게 아니다. 안쪽으로 더 들어간다.<br>더 잠긴 것이다.`, poll:7 },
    { l:'② 다른 입구를 찾는다.', dc:11, p:500,
      good:`성을 돌았다. 작은 문이 있다. 잠기지 않았다.<br><br>파수꾼은 안 잠긴 문을 보면 불안해진다.<br>왜 이 문만 안 잠갔는지 생각하면서 들어갔다.`, flag:'sideDoor',
      bad:`돌아도 없다.<br><br>문이 하나뿐인 성이다. 그런 성은 없다.<br>있다면 성이 아니라 다른 것이다.`, poll:6 }
  ] }
);

epicSlot('market', 'warden').push(
{ title:'장터 — 지킬 것이 많은 곳',
  text:`좌판이 늘어서 있고 물건이 널려 있다.<br><br>
    지킬 것이 너무 많다. 파수꾼은 이런 곳을 싫어한다.<br>
    전부 지킬 수는 없다.<br><br>
    하나만 고르면 나머지는 포기하는 셈이다.`,
  opts:[
    { l:'① 가장 값나가는 것을 지킨다.', dc:12, p:600,
      good:`제일 값나가 보이는 좌판 앞에 섰다.<br><br>아무 일도 안 일어났다.<br>다른 좌판에서도 아무 일이 안 일어났다.<br><br>지킬 필요가 없었던 것이다. 그래도 서 있었던 건 헛일이 아니다.`, flag:'guardedStall',
      bad:`서 있는 동안 등 뒤 좌판이 비었다.<br><br>가져간 사람이 없다. 그냥 비었다.<br>지키는 앞쪽만 남는 구조였다.`, poll:7 },
    { l:'② 동료와 나눠 지킨다.', co:'sync',
      coOpt:{ ask:'양쪽을 봐야 합니다. 한쪽을 맡아 주십시오.', sec:60, p:950,
        text:`혼자서는 양쪽을 못 본다.`,
        doneText:`둘이 등을 지고 섰다. 각자 반대쪽을 봤다.<br><br>한참 섰다. 아무 일도 안 일어났다.<br>일어나지 않은 게 지킨 결과인지는 알 수 없다.<br><br>파수꾼의 일은 늘 그렇다.`,
        failText:`혼자 양쪽을 보려고 고개를 돌렸다.<br><br>돌리는 사이에 반대쪽이 비었다.<br>양쪽은 혼자 못 본다.` },
      good:`지켰다.`, bad:`못 지켰다.` }
  ] }
);

epicSlot('ruin', 'warden').push(
{ title:'폐허 — 무너질 것',
  text:`기둥이 기울어 있다.<br><br>
    쓰러지면 회랑 절반이 같이 간다.<br>
    받칠 수는 있다. 받치면 못 떠난다.<br><br>
    파수꾼은 이런 선택을 자주 만난다.`,
  opts:[
    { l:'① 받침을 세워 둔다.', dc:13, kind:'break', p:750,
      good:`돌을 쌓아 괴었다. 세 번 다시 쌓았다.<br><br>손을 뗐는데 안 무너진다.<br>받치는 것과 붙잡는 건 다르다. 받치면 떠날 수 있다.<br><br>떠났다. 뒤에서 아무 소리도 안 났다.`, flag:'propped',
      bad:`괴었는데 계속 미끄러진다.<br><br>기울기가 변한다. 받칠 각도가 안 나온다.<br>손으로 잡고 있었다. 한참.`, poll:8 },
    { l:'② 그냥 무너뜨린다.', dc:14, p:700,
      doom:{ title:'무너뜨린 것', what:'돌더미에 깔렸습니다', dc:14, sec:70,
        text:`밀었다. 어차피 무너질 것이라면 지금이 낫다고 생각했다.<br><br>기둥이 간다. 옆 기둥도 간다. 줄줄이 간다.<br>생각보다 많이 간다.<br><br>뛰었다. 뛰는 방향이 틀렸다.<br>다리가 눌렸다. 무겁다.`,
        dieText:`파수꾼은 무너뜨리는 사람이 아니다.<br><br>막는 사람이다.<br>역할을 바꾸면 대개 이렇게 된다.` },
      good:`멀리서 밀어 넘겼다.<br><br>기둥 하나만 갔다. 옆은 버텼다.<br>먼지가 가라앉을 때까지 봤다.<br><br>위험한 걸 미리 치우는 것도 지키는 일이다.`, flag:'felledPillar' }
  ] }
);

epicSlot('forest', 'warden').push(
{ title:'검은 숲 — 경계',
  text:`말뚝이 박혀 있다.<br><br>
    금렵구 표시다. 파수꾼 눈에는 경계선으로 보인다.<br>
    경계선은 지키라고 있는 것이다.<br><br>
    지키는 쪽이 어느 쪽인지가 문제다.`,
  opts:[
    { l:'① 바깥쪽에 서서 지킨다.', dc:12, p:650,
      good:`밖을 등지고 안쪽을 보고 섰다.<br><br>안쪽 것이 나오지 못하게.<br>한참 섰다. 안쪽에서 뭔가 다가왔다가 물러났다.<br><br>서 있는 것만으로 물러나는 것도 있다.`, flag:'stoodBorder',
      bad:`섰는데 등 뒤가 신경 쓰인다.<br><br>안쪽을 보면 바깥이 안 보인다.<br>바깥에서 뭔가 다가오는 소리가 났다.`, poll:8 },
    { l:'② 말뚝을 보강한다.', dc:13, kind:'break', p:700,
      good:`쓰러진 말뚝을 다시 박고 사이를 메웠다.<br><br>손이 부르텄다. 경계를 고치는 건 원래 손이 상하는 일이다.<br>다 하고 나니 안쪽이 조용해졌다.<br><br>조용한 게 좋은 신호인지는 모르겠다.`, flag:'mendedFence',
      bad:`박는데 땅이 무르다.<br><br>박으면 빠지고 박으면 빠진다.<br>안쪽에서 빼고 있는 것 같기도 하다.`, poll:9 }
  ] }
);

epicSlot('lake', 'warden').push(
{ title:'거울 호수 — 지킬 수 없는 것',
  text:`물가에 서 있다.<br><br>
    지킬 것이 없다. 문도 없고 담도 없고 사람도 없다.<br>
    파수꾼이 제일 난처한 상황이다.<br><br>
    다만 물 아래에 불빛이 줄지어 지나간다.`,
  opts:[
    { l:'① 세어 본다.', dc:12, kind:'sense', p:650,
      good:`스물셋이다.<br><br>일정한 간격으로, 한 방향으로 간다.<br>어디로 가는지는 모르겠다. 다만 돌아오지는 않는다.<br><br>세어 두는 것만으로도 일은 했다.`, flag:'countedLights',
      bad:`세는데 하나가 멈춘다.<br><br>멈춰서 이쪽 아래로 온다.<br>물러났다. 불빛도 멈췄다.`, poll:8 },
    { l:'② 물가에 표식을 세운다.', dc:11, p:550,
      good:`돌을 쌓아 표시를 세웠다.<br><br>여기가 물가라는 것, 아래에 뭔가 지나간다는 것.<br>다음에 오는 사람이 알아보라고.<br><br>파수꾼이 할 수 있는 게 그거다. 알려 두는 것.`, flag:'lakeCairn',
      bad:`쌓는데 무너진다.<br><br>세 번 쌓고 세 번 무너졌다.<br>물가가 표식을 거부했다.`, poll:6 }
  ] }
);
;

