// ==========================================
// ✝ 사제 — 10장면
// ==========================================
epicSlot('gate', 'priest').push(
{ title:'성문 — 들어서는 기도',
  text:`문턱을 넘기 전에 하는 기도가 있다.<br><br>
    낯선 곳에 들어갈 때 한 번, 나올 때 한 번.<br>
    나오는 기도를 못 하는 경우가 많아서 들어가는 기도는 길게 한다.<br><br>
    아치 아래에 앉은 석상이 이쪽을 본다.`,
  opts:[
    { l:'① 길게 읊는다.', dc:12, p:650,
      good:`끝까지 읊었다. 석상이 가만히 듣는다.<br><br>다 읊자 고개를 아주 조금 숙인다.<br>돌이 숙일 수 있는 만큼 숙였다.<br><br>여기도 듣는 것이 있다는 뜻이다.`, flag:'entryPrayer',
      bad:`읊는 중에 말이 엉킨다.<br><br>외운 지 오래된 기도다.<br>석상이 이어 읊는다. 정확한 문장으로.`, poll:7 },
    { l:'② 짧게 끝낸다.', dc:10, p:450,
      good:`한 줄만 읊고 들어섰다.<br><br>길게 하면 오래 서 있게 된다. 오래 서 있으면 못 들어간다.<br>짧은 기도도 기도다.`, flag:'shortPrayer',
      bad:`짧게 끝냈는데 뭔가 덜 끝난 느낌이다.<br><br>세 걸음 걷고 돌아와 마저 읊었다.<br>그 사이에 아치가 조금 낮아져 있었다.`, poll:5 }
  ] }
);

epicSlot('village', 'priest').push(
{ title:'빈 마을 — 식은 화로 앞의 기도',
  text:`집집마다 밥상이 차려져 있다.<br><br>
    먹기 전에 하는 기도가 있다. 여기 사람들도 했을 것이다.<br>
    하다 만 자세로 멈춘 흔적이 있다.<br><br>
    손을 모은 모양의 자국이 상 위에 남았다.`,
  opts:[
    { l:'① 대신 마저 읊는다.', dc:13, kind:'heal', p:750,
      good:`상 앞에 앉아 마저 읊었다. 스물셋 집을 돌며.<br><br>다 읊고 나니 김이 멎었다. 전부 동시에.<br>식은 것이 아니라 끝난 것이다.<br><br>사제가 할 수 있는 일이 이런 종류다.`, flag:'finishedGrace',
      bad:`읊는데 목이 잠긴다.<br><br>세 집에서 멈췄다.<br>나머지 스무 집은 그대로 뒀다. 김이 계속 오른다.`, poll:8 },
    { l:'② 상을 치운다.', dc:12, p:650,
      doom:{ title:'치운 상', what:'상 앞에 앉게 됐습니다', dc:14, sec:70,
        text:`그릇을 걷었다. 예의를 갖춰서.<br><br>걷는 동안 손이 익숙해진다. 여기 밥상을 여러 번 치운 손처럼.<br>마지막 그릇을 들다 멈췄다.<br><br>바닥에 이름이 있다. 이쪽 이름이다.<br>다리가 접힌다. 앉는 자세로.`,
        dieText:`차려진 상은 먹을 사람이 있어서 차린 것이다.<br><br>스물셋 집에 스물셋이 앉았고 하나가 비어 있었다.<br>치우러 온 사람이 앉게 됐다.` },
      good:`한 상만 치웠다.<br><br>그릇을 포개 놓고 물러났다.<br>치우다 보니 나머지도 치우고 싶어졌다. 거기서 멈췄다.<br><br>멈추는 것도 판단이다.`, flag:'clearedOne' }
  ] }
);

epicSlot('forest', 'priest').push(
{ title:'검은 숲 — 기도가 안 닿는 곳',
  text:`읊어도 소리가 안 퍼진다.<br><br>
    나무가 먹는다. 말이 입 밖으로 나오자마자 사라진다.<br>
    사제에게 이런 곳은 처음이다.<br><br>
    소리가 안 닿으면 기도가 아닌가.`,
  opts:[
    { l:'① 소리 없이 읊는다.', dc:12, kind:'heal', p:700,
      good:`입만 움직였다. 소리는 안 냈다.<br><br>나무가 먹을 것이 없어졌다.<br>기도는 들리라고 하는 게 아니라 하려고 하는 것이다.<br><br>다 읊고 나니 숲이 한 뼘 밝아졌다. 기분 탓일 수도 있다.`, flag:'silentPrayer',
      bad:`소리를 안 내려는데 자꾸 샌다.<br><br>샌 만큼 나무가 먹는다.<br>먹힌 말이 나무 안에서 들린다. 이쪽 목소리로.`, poll:8 },
    { l:'② 나무에 손을 대고 읊는다.', dc:14, p:750,
      doom:{ title:'먹힌 기도', what:'나무에 손이 붙었습니다', dc:13, sec:65,
        text:`껍질에 손을 대고 읊었다.<br><br>안에서 심장 소리가 난다. 느리다.<br>읊는 박자가 그 박자에 맞춰진다.<br><br>맞추자 손이 안 떨어진다.<br>기도가 안으로 들어가는 중이다. 손을 통해서.`,
        dieText:`나무가 한 그루 늘었다.<br><br>기울지 않고 곧게 선 나무다.<br>사제는 대개 곧게 선 채로 묻힌다.` },
      good:`손을 대고 읊다가 뗐다.<br><br>손바닥에 결 자국이 남았다.<br>안에서 심장 소리가 났다. 이쪽 것보다 느렸다.<br><br>느린 만큼 오래 살았을 것이다. 그것도 생명이다.`, flag:'treePrayer' }
  ] }
);

epicSlot('castle', 'priest').push(
{ title:'성 — 예배당',
  text:`성 안에 작은 예배당이 있다.<br><br>
    신전과 다르다. 여기는 제단이 문을 향해 있다.<br>
    보통은 반대다.<br><br>
    들어오는 쪽을 맞이하게 놓은 것이 아니라, 나가는 쪽을 보게 놓았다.`,
  opts:[
    { l:'① 제단을 돌려 놓는다.', dc:13, kind:'break', p:700,
      good:`무겁다. 밀어서 반 바퀴 돌렸다.<br><br>돌려놓으니 예배당이 예배당처럼 보인다.<br>바닥에 긁힌 자국이 남았다. 돌린 자국이 하나 더 생겼다.<br><br>전에도 누가 돌렸다는 뜻이다. 반대로.`, flag:'turnedAltar',
      bad:`돌리는데 바닥에 고정돼 있다.<br><br>고정한 게 아니라 자란 것이다.<br>돌리려 할수록 단단해졌다.`, poll:7 },
    { l:'② 동료와 같이 예배한다.', co:'witness',
      coOpt:{ ask:'예배당이 있습니다. 같이 있어 줄 사람이 필요합니다.', sec:60, p:900,
        text:`혼자 하는 예배는 기도고, 둘이면 예배다.`,
        doneText:`동료가 와서 옆에 앉았다.<br><br>믿는 게 있는지는 안 물었다. 물을 필요 없다.<br>같이 앉아 있는 것만으로 예배가 된다.<br><br>일어설 때 둘 다 가벼웠다.`,
        failText:`혼자 앉아 있었다.<br><br>일어설 때 무거웠다.<br>혼자 하는 건 아무리 해도 혼자다.` },
      good:`예배가 됐다.`, bad:`기도로 끝났다.` }
  ] }
);

epicSlot('road', 'priest').push(
{ title:'끊긴 길 — 건너지 못한 이들',
  text:`길 끝에 짐이 쌓여 있다.<br><br>
    건너려다 못 건넌 사람들 것이다.<br>
    신발, 보따리, 지팡이.<br><br>
    주인 없는 물건에는 기도를 해 주는 법이 있다.`,
  opts:[
    { l:'① 한자리에 모아 기도한다.', dc:12, kind:'heal', p:700,
      good:`짐을 모아 쌓고 기도했다.<br><br>짧게. 이름을 모르니 길게 할 수가 없다.<br>기도가 끝나자 짐이 조금 가라앉았다. 흙에 묻히듯이.<br><br>묻히는 게 나은 것도 있다.`, flag:'blessedPacks',
      bad:`모으는데 하나가 안 들린다.<br><br>보따리 하나가 바닥에 붙어 있다.<br>안에 뭐가 들었는지는 안 열어 봤다.`, poll:7 },
    { l:'② 안개에 축복을 내린다.', dc:15, p:800,
      doom:{ title:'축복한 안개', what:'안개가 손을 잡았습니다', dc:14, sec:70,
        text:`손을 안개 위로 뻗어 축복했다.<br><br>안개가 반응한다. 올라온다. 손목까지.<br>축복이 닿은 것이 기뻐하는 것 같다.<br><br>기뻐하는 것이 잡는다. 당긴다.<br>축복은 거두는 법이 없다. 한 번 내리면 끝이다.`,
        dieText:`축복은 받을 준비가 된 것에게 내리는 것이다.<br><br>준비가 안 된 것에게 내리면 그것이 축복한 사람을 가진다.<br>안개가 한 뼘 두꺼워졌다.` },
      good:`손을 뻗었다가 거뒀다.<br><br>축복할 대상인지 아닌지 모르겠어서.<br>모르면 안 하는 게 맞다.<br><br>대신 길 이쪽 끝에만 표시를 남겼다. 여기까지가 축복받은 땅이라고.`, flag:'boundBlessing' }
  ] }
);

// ==========================================
// 🌿 약초꾼 — 10장면
// ==========================================
epicSlot('market', 'herbal').push(
{ title:'장터 — 말린 것들',
  text:`좌판 하나에 말린 풀이 쌓여 있다.<br><br>
    묶음마다 이름표가 달려 있다. 전부 아는 이름이다.<br>
    다만 이름과 내용물이 안 맞는다.<br><br>
    바꿔 붙인 게 아니라 원래 다른 것에 그 이름을 쓰는 곳인 모양이다.`,
  opts:[
    { l:'① 내용물대로 다시 붙인다.', dc:12, kind:'sense', p:650,
      good:`하나씩 냄새 맡고 다시 붙였다.<br><br>스물셋 묶음. 다 맞췄다.<br>맞추고 나니 좌판 주인이 고개를 숙인다. 고맙다는 뜻이었다.<br><br>잘못된 이름으로 약을 지으면 사람이 죽는다.`, flag:'relabeled',
      bad:`냄새가 다 똑같다.<br><br>말린 지 오래되면 그렇게 된다.<br>맞출 수가 없어서 전부 떼었다. 이름 없는 게 낫다.`, poll:6 },
    { l:'② 한 묶음 산다.', dc:11, p:550,
      good:`제일 상태가 좋은 것으로 샀다.<br><br>값은 안 받았다. 좌판 주인이 손을 저었다.<br>약초꾼에게는 안 받는 모양이다.<br><br>고마운 일인데 마음이 편하지는 않았다.`, flag:'boughtHerb',
      bad:`고르는데 손에 가루가 묻는다.<br><br>털어도 안 떨어진다. 스며든다.<br>손이 잠시 저렸다.`, poll:7 }
  ] }
);

epicSlot('temple', 'herbal').push(
{ title:'신전 — 마른 화병',
  text:`제단 옆에 화병이 있다.<br><br>
    꽃이 꽂혀 있다. 말랐는데 색이 남았다.<br>
    보통 마르면 색이 빠진다.<br><br>
    약초꾼은 색이 남은 마른 꽃을 조심한다.`,
  opts:[
    { l:'① 손대지 않는다.', dc:10, p:450,
      good:`안 건드렸다.<br><br>색이 남은 건 아직 안 죽었다는 뜻이다.<br>안 죽은 것은 건드리면 반응한다.<br><br>지나쳤다. 지나칠 때 향이 났다. 좋은 향이었다.`, flag:'leftFlowers',
      bad:`지나치는데 향이 따라온다.<br><br>한참 따라왔다.<br>걸음을 빨리했더니 없어졌다.`, poll:6 },
    { l:'② 한 송이 뽑는다.', dc:13, kind:'heal', p:700,
      doom:{ title:'마른 꽃', what:'향에 잠기고 있습니다', dc:13, sec:65,
        text:`뽑았다. 줄기가 젖어 있다.<br><br>마른 꽃에 젖은 줄기는 없다.<br>향이 확 퍼진다. 좋은 향이다. 너무 좋다.<br><br>무릎이 풀린다. 앉고 싶어진다.<br>약초꾼은 좋은 향이 제일 위험하다는 걸 안다. 알면서 앉았다.`,
        dieText:`화병에 꽃이 하나 늘었다.<br><br>색이 남은 채로 마를 것이다.<br>다음에 오는 약초꾼이 조심할 것이다. 아마도.` },
      good:`뽑다가 줄기가 젖은 걸 알고 도로 꽂았다.<br><br>손을 옷에 닦았다. 여러 번 닦았다.<br>향이 손에 남았다. 며칠 갈 향이다.<br><br>약초꾼은 냄새로 배운다. 이것도 배운 것이다.`, flag:'wetStem' }
  ] }
);

epicSlot('grave', 'herbal').push(
{ title:'묘지 — 풀이 없는 이유',
  text:`잡초가 한 포기도 없다.<br><br>
    손질한 것치고는 너무 깨끗하다. 뽑은 자국도 없다.<br>
    약초꾼은 풀이 안 나는 땅을 안다.<br><br>
    대개는 아래에 뭔가 있다.`,
  opts:[
    { l:'① 흙을 만져 본다.', dc:12, kind:'sense', p:650,
      good:`손가락으로 비벼 봤다. 마르지 않았는데 푸석하다.<br><br>양분이 빠진 흙이다. 위로 안 가고 아래로 갔다.<br>아래에 있는 것이 다 먹고 있다는 뜻이다.<br><br>스물셋 기 전부 그렇다.`, flag:'deadSoil',
      bad:`만지자 흙이 따뜻하다.<br><br>겨울 흙이 아니다.<br>손을 털고 물러났다.`, poll:7 },
    { l:'② 씨를 뿌려 본다.', dc:11, kind:'heal', p:600,
      good:`가진 씨를 조금 뿌렸다. 덮고 물을 줬다.<br><br>나지 않을 것이다. 그래도 뿌렸다.<br>약초꾼은 안 날 자리에도 뿌린다. 그게 직업이다.<br><br>돌아보니 한 자리만 싹이 텄다. 비석 없는 봉분이다.`, flag:'sowedGrave',
      bad:`뿌리는데 바람이 없는데 씨가 날아간다.<br><br>흩어져 버렸다.<br>받아 주지 않는 땅이었다.`, poll:6 }
  ] }
);

epicSlot('road', 'herbal').push(
{ title:'끊긴 길 — 약을 나눈다',
  text:`길에 누가 앉아 있다.<br><br>
    동료 중 하나다. 다리를 감싸고 있다.<br>
    약초꾼이 지나가면 앉아 있는 사람이 보인다.<br><br>
    안 보이면 약초꾼이 아니다.`,
  opts:[
    { l:'① 치료해 준다.', co:'call',
      coOpt:{ ask:'다친 사람이 있습니다. 부축할 손이 필요합니다.', sec:60, p:950,
        text:`치료는 혼자 해도 옮기는 건 둘이 해야 한다.`,
        doneText:`둘이 부축해 옮겼다.<br><br>상처를 씻고 약초를 붙이고 감았다.<br>붙인 자리가 따뜻해진다. 좋은 신호다.<br><br>일어나 걸었다. 절뚝이긴 했지만 걸었다.`,
        failText:`혼자 치료했다.<br><br>옮길 수는 없었다. 길가에 눕혀 두고 갔다.<br>돌아보니 그대로 앉아 있었다.` },
      good:`치료했다.`, bad:`두고 갔다.`, flag:'treatedOne' },
    { l:'② 약만 건네고 간다.', dc:11, p:500,
      good:`병을 쥐여 주고 쓰는 법을 말해 줬다.<br><br>알아들었는지는 모르겠다. 고개는 끄덕였다.<br>약초꾼이 늘 하는 일이다. 주고 가는 것.`, flag:'gaveVial',
      bad:`건넸는데 안 받는다.<br><br>손이 안 움직인다. 이미 그런 상태였다.<br>병을 옆에 놓고 갔다.`, poll:8 }
  ] }
);

epicSlot('tower', 'herbal').push(
{ title:'탑 — 높은 데 나는 것',
  text:`탑 꼭대기 틈에 풀이 자란다.<br><br>
    흙도 없는데 자란다. 돌 틈에 뿌리를 박았다.<br>
    이런 것은 대개 독하다.<br><br>
    독한 게 약이 되는 경우가 많다.`,
  opts:[
    { l:'① 뿌리째 캔다.', dc:14, kind:'heal', p:800,
      good:`돌 틈을 벌려 뽑았다. 뿌리가 길다.<br><br>탑 안쪽까지 들어가 있었다. 벽을 잡고 있던 것이다.<br>뽑자 탑이 한 번 흔들렸다.<br><br>흔들리고 멎었다. 이 정도는 버티는 모양이다.`, flag:'towerRoot',
      bad:`뽑는데 뿌리가 안 끊긴다.<br><br>당길수록 나온다. 계단을 따라 내려간다.<br>중간에 놓았다.`, poll:8 },
    { l:'② 잎만 딴다.', dc:11, p:600,
      good:`잎만 몇 장 땄다. 뿌리는 뒀다.<br><br>탑이 안 흔들렸다.<br>잎만 따는 게 옳았다. 이 풀은 여기 있어야 한다.`, flag:'towerLeaf',
      bad:`따는데 잎이 손에 감긴다.<br><br>덩굴이 아닌데 감긴다.<br>풀어 내는 데 시간이 걸렸다.`, poll:6 }
  ] }
);

// ==========================================
// 🕯 산파 — 10장면
// ==========================================
epicSlot('lake', 'midwife').push(
{ title:'거울 호수 — 물가의 알',
  text:`물가에 알이 있다.<br><br>
    여섯 개. 따뜻하다.<br>
    산파는 알을 봐도 손이 먼저 나간다. 직업병이다.<br><br>
    깨지려는 것이 하나 있다.`,
  opts:[
    { l:'① 받아 준다.', dc:13, kind:'heal', p:750,
      good:`손을 대고 기다렸다.<br><br>안에서 밀고 나온다. 껍질이 갈라진다.<br>받았다. 작다. 미끄럽다. 무겁지 않다.<br><br>물가에 내려놓으니 물로 들어갔다. 돌아보지 않았다.<br>돌아보지 않는 게 맞다.`, flag:'hatched',
      bad:`받으려는데 안에서 안 나온다.<br><br>갈라진 채로 멎었다.<br>기다렸다. 오래 기다렸다. 그대로였다.`, poll:8 },
    { l:'② 물로 밀어 준다.', dc:11, p:600,
      good:`알을 물 쪽으로 굴려 줬다.<br><br>물에 닿자 나머지 다섯도 같이 굴러 들어갔다.<br>스스로 간 것인지 물이 당긴 것인지 모르겠다.<br><br>받아 주는 것만이 산파의 일은 아니다.`, flag:'rolledEggs',
      bad:`미는데 하나가 깨진다.<br><br>손 밑에서. 안에 든 것이 나오지 않았다.<br>덮어 뒀다.`, poll:9 }
  ] }
);

epicSlot('temple', 'midwife').push(
{ title:'신전 — 손을 씻는다',
  text:`성수반이 있다.<br><br>
    산파는 받기 전에 손을 씻는다. 그게 제일 중요하다.<br>
    여기 물이 성수인지 그냥 물인지는 상관없다.<br><br>
    씻는다는 행위가 중요하다.`,
  opts:[
    { l:'① 씻는다.', dc:11, kind:'heal', p:600,
      good:`손을 담갔다. 차다.<br><br>손톱 밑까지 문질렀다. 배운 대로.<br>씻고 나니 손이 가볍다. 받을 준비가 된 손이다.<br><br>준비된 손으로 아무것도 안 받고 나오는 날도 있다.`, flag:'washedHands',
      bad:`씻는데 물이 탁해진다.<br><br>손에서 나온 게 아니다. 아래에서 올라왔다.<br>얼른 뺐다.`, poll:7 },
    { l:'② 성수를 받아 간다.', dc:12, p:650,
      good:`병에 담았다.<br><br>받을 때 쓸 것이다. 깨끗한 물은 어디서나 귀하다.<br>여기서는 특히.`, flag:'holyWater',
      bad:`담는데 병이 무거워진다.<br><br>물보다 무겁다.<br>따라 보니 그냥 물이다. 무게만 이상했다.`, poll:6 }
  ] }
);

epicSlot('forest', 'midwife').push(
{ title:'검은 숲 — 둥지',
  text:`나무 아래에 둥지가 있다.<br><br>
    땅에 지은 둥지다. 새가 아니다.<br>
    안에 여럿 있다. 아직 눈도 안 떴다.<br><br>
    어미가 안 보인다.`,
  opts:[
    { l:'① 덮어 준다.', dc:11, kind:'heal', p:600,
      good:`낙엽을 모아 덮어 줬다. 숨구멍은 남기고.<br><br>산파가 할 수 있는 게 그 정도다.<br>어미는 돌아올 것이다. 안 돌아와도 어쩔 수 없다.<br><br>덮고 나서 한참 서 있다 갔다.`, flag:'coveredNest',
      bad:`덮는데 하나가 기어 나온다.<br><br>눈도 안 뜬 게 이쪽으로 온다.<br>냄새를 아는 모양이다. 손 냄새를.`, poll:8 },
    { l:'② 어미를 찾는다.', dc:13, kind:'sense', p:700,
      doom:{ title:'어미', what:'어미가 돌아왔습니다', dc:14, sec:70,
        text:`자국을 따라갔다. 크다. 아주 크다.<br><br>어미가 이쪽으로 오고 있다는 걸 알았을 때는 늦었다.<br>둥지와 이쪽 사이에 선 자세다.<br><br>새끼를 만진 손 냄새가 난다. 그게 문제다.<br>산파의 손은 늘 무언가를 만진 손이다.`,
        dieText:`어미는 새끼 냄새가 나는 것을 안 봐준다.<br><br>도와준 것과 가져가려 한 것을 구분하지 못한다.<br>구분할 이유도 없다.` },
      good:`자국을 따라가다 멈췄다.<br><br>크다. 이 자국의 주인은 만나면 안 된다.<br>둥지로 돌아가 냄새를 지웠다. 흙을 문질러서.<br><br>어미가 돌아왔을 때 이쪽 냄새가 없어야 한다.`, flag:'maskedScent' }
  ] }
);

epicSlot('castle', 'midwife').push(
{ title:'성 — 아이 방',
  text:`방 하나가 작다.<br><br>
    침대가 작고 천장이 낮다. 아이 방이다.<br>
    쓰던 흔적이 있다. 오래되지 않았다.<br><br>
    벽에 키를 잰 금이 있다. 마을 집에서 본 것과 같은 방식.`,
  opts:[
    { l:'① 금을 읽는다.', dc:12, kind:'gaze', p:650,
      good:`금이 열두 개. 해마다 하나씩이다.<br><br>마지막 금이 그 위 것보다 아래에 있다.<br>줄어든 것이다.<br><br>자라다 줄어드는 건 사람이 하는 일이 아니다.`, flag:'shrankChild',
      bad:`읽는데 금이 하나 더 생긴다.<br><br>보는 앞에서. 맨 위에.<br>이쪽 키 높이다.`, poll:9 },
    { l:'② 침대를 정리한다.', dc:11, kind:'heal', p:600,
      good:`이불을 펴고 베개를 놓았다.<br><br>쓸 사람이 없어도 정리는 한다.<br>산파는 받고 나서 자리를 정리하는 데까지가 일이다.<br><br>정리하고 나니 방이 조금 넓어 보였다.`, flag:'madeBed',
      bad:`이불을 드니 눌린 자국이 있다.<br><br>방금까지 누워 있던 자국이다. 따뜻하다.<br>도로 덮었다.`, poll:8 }
  ] }
);

epicSlot('road', 'midwife').push(
{ title:'끊긴 길 — 업고 건넌다',
  text:`끊긴 자리 앞이다.<br><br>
    산파는 늘 무언가를 안거나 업고 다닌다.<br>
    지금은 자루 하나뿐인데도 무겁다.<br><br>
    안개 위를 건너려면 가벼워야 할 것 같다.`,
  opts:[
    { l:'① 동료와 번갈아 든다.', co:'handoff',
      coOpt:{ ask:'무거운 것이 있습니다. 번갈아 들어 주십시오.', sec:60, p:950,
        text:`번갈아 들면 둘 다 건넌다.`,
        doneText:`번갈아 들며 건넜다.<br><br>든 쪽이 무겁고 안 든 쪽이 가볍다. 번갈아 하니 둘 다 견딜 만했다.<br>건너편에 닿아 내려놓았다.<br><br>자루가 갑자기 가벼워졌다. 건너오면 가벼워지는 것이었다.`,
        failText:`혼자 들고 건넜다.<br><br>무릎까지 빠졌다. 세 번 빠졌다.<br>건너긴 했다. 신발 한 짝을 두고 왔다.` },
      good:`건넜다.`, bad:`겨우 건넜다.`, flag:'tookTurns' },
    { l:'② 내려놓고 건넌다.', dc:11, p:550,
      good:`자루를 길에 두고 건넜다.<br><br>가벼웠다. 한 번에 건넜다.<br>건너편에서 돌아보니 자루가 없다.<br><br>없어진 게 나은 것도 있다.`, flag:'leftBurden',
      bad:`내려놓으려는데 손이 안 펴진다.<br><br>산파의 손은 놓는 걸 늦게 배운다.<br>들고 건넜다. 오래 걸렸다.`, poll:8 }
  ] }
);
;
